CREATE FUNCTION verundentsorgung.admin_aw_lin_topologie_update(vtg_op text, vtable_schema text, vid_aw_lin_haltung uuid, vid_st_vw_projekt uuid, vgueltig_von timestamp with time zone, vgueltig_bis timestamp with time zone, vangelegt_am timestamp with time zone, vangelegt_von text, vgeaendert_am timestamp with time zone, vgeaendert_von text, vbemerkung text, vid_knoten_oben uuid, vid_knoten_unten uuid, vgeometry public.geometry, vlayout jsonb, vid_st_vw_medium uuid) RETURNS text
    LANGUAGE plpgsql
    AS $_$
declare
vPROJEKTPARAMETER_WERT_KURZTEXT           text;
vPROJEKTPARAMETER_WERT_AKTIVSTATUS        numeric;
vPROJEKTPARAMETER_WERT_NUMERIC            numeric;
vPROJEKTPARAMETER_WERT_TEXT               text;
