	geaendert_am, -- timestamptz, -- DEFAULT now() NOT NULL,
	geaendert_von, -- text, -- DEFAULT ''unbekannt''::text NOT NULL,
	bemerkung, -- text, -- NULL,
	id_knoten_oben, -- uuid, -- DEFAULT ''00000000-0000-0000-0000-000000000000''::uuid NULL,
	id_knoten_unten, -- uuid, -- DEFAULT ''00000000-0000-0000-0000-000000000000''::uuid NULL,
	geometry, -- public.geometry(linestring, 25833) --NOT NULL,
	layout, -- jsonb -- NULL
	richtungswinkel, -- numeric(3, 3), -- NOT NULL,
	mittelpunkt, -- public.geometry(point, 25833), -- NOT NULL,
    laenge, -- numeric
    laufendenummer_in_geometrie, --int not null,
    id
	) select  
	$1 , --vid_aw_lin_haltung uuid, -- NOT NULL,
	$2 , --vid_st_vw_projekt , -- uuid, -- DEFAULT ''00000000-0000-0000-0000-000000000000''::uuid NOT NULL,
	$3 , --vgueltig_von , -- timestamptz, -- DEFAULT now() NOT NULL,
	$4 , --vgueltig_bis , -- timestamptz, -- DEFAULT ''2100-01-01 00:00:00+01''::timestamp with time zone NOT NULL,
	$5 , --vangelegt_am , -- timestamptz, -- DEFAULT now() NOT NULL,
	$6 , --vangelegt_von , -- text, -- DEFAULT ''unbekannt''::text NOT NULL,
	$7 , --vgeaendert_am , -- timestamptz, -- DEFAULT now() NOT NULL,
	$8 , --vgeaendert_von , -- text, -- DEFAULT ''unbekannt''::text NOT NULL,
	$9 , --vbemerkung , -- text, -- NULL,
	$10 , --vid_knoten_oben , -- uuid, -- DEFAULT ''00000000-0000-0000-0000-000000000000''::uuid NULL,
	$11 , --vid_knoten_unten , -- uuid, -- DEFAULT ''00000000-0000-0000-0000-000000000000''::uuid NULL,
	$12 , --vgeometry , -- public.geometry(linestring, 25833) NOT NULL,
	$13 , --vlayout , -- jsonb NULL
