if vEXECUTE = 1 then execute vSQL using vid_aw_lin_haltung , vid_st_vw_projekt , vgueltig_von , vgueltig_bis , vangelegt_am , vangelegt_von , vgeaendert_am , vgeaendert_von , vbemerkung , vid_knoten_oben , vid_knoten_unten , vSPLIT_SEGMENT , vlayout, vrichtungswinkel, vpkt_vektormitte, vlaenge, vZ, vUUID_aw_lin_topologie; end if;
