      vSQLAKTIVSTATUSABFRAGE := 'select wert_aktivstatus, wert_numerisch, wert_text, wert_timestamptz, id_st_vw_projekt, notiz, fehlermeldung, sortierreihenfolge, bemerkung from '||vTABLE_SCHEMA||'.admin_projekt_parameter where kurztext = $1 and id_st_vw_projekt = $2';
 	  execute vSQLAKTIVSTATUSABFRAGE into vPROJEKTPARAMETER_WERT_AKTIVSTATUS, vPROJEKTPARAMETER_WERT_NUMERIC, vPROJEKTPARAMETER_WERT_text, vPROJEKTPARAMETER_WERT_TIMESTAMP, vPROJEKTPARAMETER_WERT_id_st_vw_projekt, vPROJEKTPARAMETER_WERT_notiz, vPROJEKTPARAMETER_WERT_fehlermeldung, vPROJEKTPARAMETER_WERT_SORTIERREIHENFOLGE, vPROJEKTPARAMETER_WERT_BEMERKUNG using vPROJEKTPARAMETER_WERT_KURZTEXT, vid_st_vw_projekt;
        if     vPROJEKTPARAMETER_WERT_AKTIVSTATUS > 0 then
          --
          vSQL := 'select kurztext from '||vtable_schema||'.st_vw_medium where id_st_vw_projekt = $1 and id = $2';
            if vNOTICE  = 1 then raise notice '%', concat('vSQL: ', vSQL::text); end if;
            if vEXECUTE = 1 then execute vSQL into vst_vw_medium_kurztext using vid_st_vw_projekt, vid_st_vw_medium ; end if;
