CREATE FUNCTION verundentsorgung.admin_delete_vectoren(vscript_name text) RETURNS text
    LANGUAGE plpgsql
    AS $_$
--
declare
vSQL text;
vRC record;
vgeometry public.geometry(polygon, 25833) default st_geomfromtext('POLYGON((245977 5981540,248697 5981540,248697 5984797,245977 5984797,245977 5981540))',25833);
begin
if vscript_name = 'admin_delete_vectoren' then
vSQL := 'select table_schema, table_name from information_schema.tables where table_schema like ''verundentsorgung'' 
  and (table_schema, table_name) not in (select table_schema, table_name from information_schema.views)
  and (table_schema, table_name, ''geometry'') in (select table_schema, table_name, column_name from information_schema.columns)
  and substr(table_name,1,2) in (''aw'',''wa'',''ka'',''st'') order by 1,2';
for vRC in execute vSQL loop
vSQL := 'delete from '||vRC.table_schema||'.'||vrc.table_name||' where st_intersects(geometry, $1) = ''f'' ';
raise notice '%', vSQL; execute vSQL using vgeometry;
end loop;
end if;
--
return vRETURN::text;
end;
$_$;


