--
-- TOC entry 28619 (class 1255 OID 39683363)
-- Name: admin_entwicklungen(text); Type: FUNCTION; Schema: verundentsorgung; Owner: -
--

CREATE FUNCTION verundentsorgung.admin_entwicklungen(vscript_name text) RETURNS text
    LANGUAGE plpgsql
    AS $_$
declare
vRETURN       text default 't';
vZ            integer default 0;
vZ1           integer default 0;
vZ2           integer default 0;
vDUMMY        text default 'Fehler!';
vSQL          text default 'Fehler!';
vRC           RECORD;
vRC_TABLES    RECORD;
vQUELLSCHEMA  text default 'verundentsorgung_oracle';
vQUELLTABELLE text default 'verundentsorgung';
vZIELSCHEMA   text default 'verundentsorgung';
vZIELTABELLE  text default 'verundentsorgung';
vscript       text default 'Fehler!';
vPROJEKT_NAME text default 'ZVG';
vID_PROJEKT   text default '00000000-0000-0000-0000-000000000001';
vID_DEFAULT   text default '00000000-0000-0000-0000-000000000000';
vKURZTEXT_DEFAULT   text default 'unbekannt';
vMIGRATIONTESTORT   text default 'Grevesmühlen';
vEXECUTE            integer default 1;

begin
vSQL := 'select id from "'||vZIELSCHEMA||'"."st_vw_projekt" where kurztext = $1'; execute vSQL into vID_PROJEKT using vPROJEKT_NAME;
--Doku: 
/*
select verundentsorgung.admin_entwicklungen('count_all_schema_tables'::text);
select verundentsorgung.admin_entwicklungen('create_views'::text);
select verundentsorgung.admin_entwicklungen('create_triggers'::text);
select verundentsorgung.admin_entwicklungen('add_columns'::text);
select verundentsorgung.admin_entwicklungen('001_delete_all_schema_tables'::text);
select verundentsorgung.admin_entwicklungen('002_insert_strassenschluessel'::text);
select verundentsorgung.admin_entwicklungen('003_insert_aw_lin_haltung'::text);
*/
--
--
-- select verundentsorgung.admin_entwicklungen('count_all_schema_tables'::text);



if vscript_name = 'rename_foreign_key' then
raise notice '%', vscript_name;
/*declare
vSQL text;
vRC record;
vEXECUTE integer default 1;
begin*/
raise notice '%', 'Beginn';
	vSQL := 'SELECT
tc.table_schema,
tc.constraint_name,
tc.table_name,
kcu.column_name,
ccu.table_schema AS foreign_table_schema,
ccu.table_name AS foreign_table_name,
ccu.column_name AS foreign_column_name
FROM information_schema.table_constraints AS tc
JOIN information_schema.key_column_usage AS kcu
ON tc.constraint_name = kcu.constraint_name
AND tc.table_schema = kcu.table_schema
JOIN information_schema.constraint_column_usage AS ccu
ON ccu.constraint_name = tc.constraint_name
where tc.table_schema in (''verundentsorgung'') --and tc.table_name = ''wa_lin_wasserleitung''
and tc.constraint_name like ''%fk'' ';
for vRC in execute vSQL loop
vSQL := 'ALTER TABLE '||vRC.table_schema||'.'||vRC.table_name||' drop constraint '||vrc.constraint_name;
raise notice '%', vSQL;	if vEXECUTE = 1 then execute vSQL; end if;
vSQL := 'ALTER TABLE '||vRC.table_schema||'.'||vRC.table_name||' add constraint '||'fk_'||substring(vrc.constraint_name,1,length(vrc.constraint_name)-3)||' FOREIGN KEY ('||vRC.column_name||') REFERENCES '|| vRC.table_schema ||'.'||vrc.foreign_table_name||'(ID) ';
raise notice '%', vSQL;	if vEXECUTE = 1 then execute vSQL; end if;
end loop;
end if; --if vscript_name = 'rename_foreign_key' then




if vscript_name = 'count_all_schema_tables' then
raise notice '%', vscript_name;
vSQL := 'select * from pg_tables where schemaname = $1';
for vRC in execute vSQL using vZIELSCHEMA loop
	vSQL := 'select count(*) anzahl,
               /*  , concat(
                   count(*)::text                 -- anzahl
                 ,'', '', '''||vRC.schemaname||'''::text -- table_schema
                 ,'', '', '''||vRC.tablename||'''::text  -- table_name 
                           ) s, */
                  ''select * from "'||vRC.schemaname||'"."'||vRC.tablename||'"; --''||count(*)::text s1
                   from "'||vRC.schemaname||'"."'||vRC.tablename||'"';
    execute vSQL into vZ, vRETURN; if vZ > 0 then raise notice '%', vRETURN; end if;
end loop; --for vRC in execute vSQL using vZIELSCHEMA loop
end if; --if vscript_name = 'count_all_schema_tables' then
