--
if vscript_name = 'create_vw_views' then
raise notice '%', vscript_name;
vZIELSCHEMA := 'verundentsorgung';
vSQL := 'select * from pg_tables where schemaname = $1 and substring(tablename,3,4) in (''_vw_'') order by schemaname, tablename'; --vorlage
for vRC in execute vSQL using vZIELSCHEMA loop
	vSQL := concat('DROP VIEW "', vRC.schemaname, '"."', vRC.tablename, '_v"'); raise notice '%', vSQL||';'; --execute vSQL;
	vSQL := concat('CREATE VIEW "', vRC.schemaname, '"."', vRC.tablename, '_v" as 
SELECT b.id, b.ident_hist, b.kurztext, b.langtext,  concat(b.kurztext,'' ('' , b.langtext, '')'') anzeige,  b.bemerkung, b.sortierreihenfolge, b.gueltig_von, b.gueltig_bis, b.angelegt_am, b.angelegt_von, b.geaendert_am, b.geaendert_von
', case when vRC.tablename = 'st_vw_projekt' then '' else ', b.id_st_vw_projekt' end, '
FROM "', vRC.schemaname, '"."', vRC.tablename, '" b');
raise notice '%', vSQL||';'; execute vSQL;
vSQL := concat('GRANT ALL ON TABLE "', vRC.schemaname, '"."', vRC.tablename, '_v" TO verundentsorgung_admin_rolle'); raise notice '%', vSQL||';'; execute vSQL;
end loop; --for vRC in execute vSQL using vZIELSCHEMA loop
end if; --vscript_name = 'create_vw_views'
--
--
--  
if vscript_name = 'create_views' then
raise notice '%', vscript_name;
vZIELSCHEMA := 'verundentsorgung';
vSQL := 'select * from pg_tables where schemaname = $1 and left(tablename,3) in ( ''aw_'', ''ka_'', ''ta_'', ''wa_'' ) order by schemaname, tablename'; --vorlage
for vRC in execute vSQL using vZIELSCHEMA loop
	vSQL := concat('DROP VIEW "', vRC.schemaname, '"."', vRC.tablename, '_v"'); raise notice '%', vSQL; execute vSQL;
	vSQL := concat('CREATE VIEW "', vRC.schemaname, '"."', vRC.tablename, '_v" as 
select 
  b.id::text id
, b.fid_hist::text fid_hist
, b.name_number::text name_number
, left(b.gueltig_von::text,16)::text gueltig_von
, left(b.gueltig_bis::text,16)::text gueltig_bis
, left(b.angelegt_am::text,10)::text angelegt_am
, b.angelegt_von::text angelegt_von
, left(b.geaendert_am::text,10)::text geaendert_am
, b.geaendert_von::text geaendert_von
, b.leistungsobjekt::text leistungsobjekt
, b.bemerkung::text bemerkung
, b.id_st_strasse::text id_st_strasse
, b.hausnummer::text hausnummer
, b.hausnummerzusatz::text hausnummerzusatz
, b.lagezusatz::text lagezusatz
, b.herkunftsplan::text herkunftsplan
, b.id_st_vw_projekt::text id_st_vw_projekt
, b.id_st_vw_betriebsstatus::text id_st_vw_betriebsstatus
, b.id_st_vw_eigentuemer::text id_st_vw_eigentuemer
, b.id_st_vw_betreiber::text id_st_vw_betreiber
, b.id_st_vw_material::text id_st_vw_material
, b.id_st_vw_medium::text id_st_vw_medium
, b.id_st_vw_lagestatus::text id_st_vw_lagestatus
, b.geometry
, s.amt::text amt
, s.gemeinde::text gemeinde
, s.ort::text ort
, s.strasse::text strasse
, p.kurztext::text projekt_kurztext
, p.langtext::text projekt_langtext
, bs.kurztext::text betriebsstatus_kurztext
, bs.langtext::text betriebsstatus_langtext
, eig.kurztext::text eigentuemer_kurztext
, eig.langtext::text eigentuemer_langtext
, betr.kurztext::text betreiber_kurztext
, betr.langtext::text betreiber_langtext
, mat.kurztext::text material_kurztext
, mat.langtext::text material_langtext
, med.kurztext::text medium_kurztext
, med.langtext::text medium_langtext
, ls.kurztext::text lagestatus_kurztext
, ls.langtext::text lagestatus_langtext
, b.baujahr::text   baujahr
', case when vRC.tablename = 'aw_lin_haltung' then '
    , b.id_knoten_oben::text
    , b.id_knoten_unten::text
	, b.nennweite::text                
	, b.aussendurchmesser::text        
	, b.sohle_einlaufschacht::text     
	, b.fallhoehe_einlaufschacht::text 
	, b.einlaufnummer::text            
	, b.ablaufhoehe::text              
	, b.auslaufnummer::text            
	, b.einlaufhoehe::text             
	, b.laenge::text                   
	, b.sohle_ablaufschacht::text      
	, b.haltungsgefaelle::text         
	, b.wandstaerke::text              
' else '' end, 
' from "', vRC.schemaname, '"."', vRC.tablename, '" b
left join verundentsorgung.strassenschluessel_v s    on b.id_st_strasse::text            = s.id::text
left join verundentsorgung.st_vw_projekt        p    on b.id_st_vw_projekt::text         = p.id::text
left join verundentsorgung.st_vw_betriebsstatus bs   on b.id_st_vw_betriebsstatus::text  = bs.id::text
left join verundentsorgung.st_vw_eigentuemer    eig  on b.id_st_vw_eigentuemer::text     = eig.id::text
left join verundentsorgung.st_vw_betreiber      betr on b.id_st_vw_betreiber::text       = betr.id::text
left join verundentsorgung.st_vw_material       mat  on b.id_st_vw_material::text        = mat.id::text
left join verundentsorgung.st_vw_medium         med  on b.id_st_vw_medium::text          = med.id::text
left join verundentsorgung.st_vw_lagestatus     ls   on b.id_st_vw_lagestatus::text      = ls.id::text
WHERE b.gueltig_bis > now()');
raise notice '%', vSQL; execute vSQL;
end loop; --for vRC in execute vSQL using vZIELSCHEMA loop
end if; --vscript_name = 'create_views'
