raise notice '%', vscript_name;
vZIELSCHEMA := 'verundentsorgung';
vSQL := 'select ''migrationsdatum''   column_name, ''timestamp'' data_type, ''now()'' default_value
   --select ''baujahr''   column_name, ''integer'' data_type, ''1900'' default_value
   --union select ''bemerkung'' column_name, ''text'' data_type, ''''''noch keine Bemerkung'''''' default_value
        '; --alle anzulegenden columns
for vRC in execute VSQL loop --alle anzulegenden columns Schleife öffnen
  vSQL := 'select t.schemaname table_schema, t.tablename table_name from pg_tables t
             where 
                  t.schemaname = $1 and left(t.tablename, 3) in ( ''aw_'', ''ka_'', ''ta_'', ''wa_'' )
             and (t.schemaname, t.tablename) not in (select v.table_schema, v.table_name from information_schema.views v) ';
            --alle Tabellen, die betroffen sind
  for vRC_TABLES in execute vSQL using vZIELSCHEMA loop --alle Tabellen, die betroffen sind Schleife öffnen
  	vSQL := 'select count(*) z from information_schema.columns where table_schema = $1 and table_name = $2 and column_name = $3';
      execute vSQL into vZ using vZIELSCHEMA, vRC_TABLES.table_name, vRC.column_name;
      if vZ = 0 then 
        --vSQL := 'alter table "'||vZIELSCHEMA||'"."'||vRC_TABLES.table_name||'" drop column "'||vRC.column_name||'" ';
        --raise notice '%', vSQL; execute vSQL;
        vSQL := 'alter table "'||vZIELSCHEMA||'"."'||vRC_TABLES.table_name||'" add "'||vRC.column_name||'" '||vRC.data_type||' not null default '||vRC.default_value||'';
        raise notice '%', vSQL; execute vSQL;
        --vSQL := 'alter table "'||vZIELSCHEMA||'"."'||vRC_TABLES.table_name||'" add constraint ck_'||vRC_TABLES.table_name||'_'||vRC.column_name||' check ('||vRC.column_name||' between 1800 and 2050 )';
        --raise notice '%', vSQL; execute vSQL;
      end if;
  end loop; --alle Tabellen, die betroffen sind Schleife öffnen	
end loop; -- for vRC in execute VSQL loop
end if; --if vscript_name = 'add_columns' then
