 ( ident_hist, amt, id_st_vw_projekt ) '||'
   select
      q.id::text  id
    , q.amt::text amt
    , $1             id_st_vw_projekt
   from "'||vQUELLSCHEMA||'"."'||vQUELLTABELLE||'" q
     where not exists ( select ''X'' from "'||vZIELSCHEMA||'"."'||vZIELTABELLE||'" z where z.ident_hist = q.id::text )';
