raise notice '%', vSQL; execute vSQL using vID_DEFAULT, vID_DEFAULT, vKURZTEXT_DEFAULT, vID_PROJEKT, vID_DEFAULT, vID_DEFAULT;
vSQL := 'insert into "'||vZIELSCHEMA||'"."'||vZIELTABELLE||'" ( ident_hist, ort, id_st_vw_projekt, id_st_gemeinde ) '||'
