--CONSTRAINT uk1_st_amt UNIQUE (id_st_vw_projekt, amt),
--
--vSQL := 'select * from pg_tables where schemaname = $1 and left(tablename,5) like ''v_ww_'' order by tablename'; 
--for vRC_TABLES in vSQL using vQUELLSCHEMA loop
for vRC in (
select 'st_vw_betriebsstatus'        T, 'betriebsstatus'        C, 'langtext' ZF  union
select 'st_vw_lagestatus'            T, 'lagestatus'            C, 'langtext' ZF  union
select 'st_vw_material'              T, 'material'              C, 'langtext' ZF  union
select 'st_vw_betreiber'             T, 'betreiber'             C, 'langtext' ZF  union
select 'st_vw_eigentuemer'           T, 'eigentuemer'           C, 'langtext' ZF  union
select 'st_vw_medium'                T, 'hydraulic_function'    C, 'langtext' ZF  
) loop
vSQL := 'insert into "'||vZIELSCHEMA||'"."'||vRC.T||'"
         ( id, kurztext, langtext ) select ''00000000-0000-0000-0000-000000000000'',''unbekannt'',''unbekannt'' where not exists
         ( select ''X'' from "'||vZIELSCHEMA||'"."'||vRC.T||'" where id = ''00000000-0000-0000-0000-000000000000'')';
raise notice '%', vSQL; execute vSQL;
vSQL := 'select count(*) z from information_schema.columns where table_schema = $1 and table_name = $2 and column_name = $3         '; execute vSQL into vZ1 using vQUELLSCHEMA, vQUELLTABELLE, vRC.C;
