--
-- TOC entry 28807 (class 1255 OID 63527172)
-- Name: admin_isybau_dateianbindung(text, text, text, text); Type: PROCEDURE; Schema: verundentsorgung; Owner: -
--

CREATE PROCEDURE verundentsorgung.admin_isybau_dateianbindung(vtabellenpraefix text, vmandant text, vnotice text, vexecute text)
    LANGUAGE plpgsql
    AS $$
declare
---
--- Baustelle!!!
---
--vNOTICE      varchar default '1';
--vEXECUTE     varchar default '1';
--vTABELLENPRAEFIX varchar default null; --'rev01_'
--vTABELLENPRAEFIX varchar default 'ta_'; --'rev01_'
vQUELLSCHEMA    varchar default 'verundentsorgung';
vZIELSCHEMA     varchar default 'verundentsorgung';
vobjekt_tabelle_schema varchar default 'verundentsorgung';
vPROJEKT_KURZTEXT varchar default upper(vmandant);
vid_st_vw_projekt uuid;
--vGWSZIELPROJEKT   varchar default 'os_'||lower(vmandant)||'_leitungbestand';
vGWSZIELPROJEKT   varchar default 'kowa_leitungbestand_'||lower(vmandant); --kowa_leitungbestand_zvg
vRCTNAME     record;
vrc          record;
vrc_columns  record;
vSQL         varchar;
vCOLUMN_LIST varchar default null; 
vZ           integer;
vZALT        integer;
vZNEU        integer;
vVIEWNAME    text default '%'; --temporäre Einschränkung default '%'
vTABLE_NAME  varchar;
vZTWSZ       integer;
vDUMMY       text;
vNOTICEVACUUM  text default '1'; 
vEXECUTEVACUUM text default '0'; --if vEXECUTEVACUUM = '1' then perform "admin".admin_vacuum_schema_table( 'verundentsorgung', 'tabellenname'); end if;
begin
--
--call verundentsorgung.admin_isybau_dateianbindung('isybaudokumente','zvg','1','0');
--
if vtabellenpraefix = 'isybaudokumente' and vmandant = 'zvg' then
  select count(*) into vZ from verundentsorgung.st_dokument2objekt 
    where id_st_dokument::uuid in ( select id::uuid from verundentsorgung.st_dokument where bemerkung = 'periodischer temporärer Import durch Job' );
  raise notice '%', concat('Es werden ', vZ::text, ' DS aus verundentsorgung.st_dokument2objekt gelöscht');
--
if vexecute = '1' then
  delete from verundentsorgung.st_dokument2objekt 
    where id_st_dokument::uuid in ( select id::uuid from verundentsorgung.st_dokument where bemerkung = 'periodischer temporärer Import durch Job' );
end if; --if vexecute = '1' then
--
--
--
select count(*) into vZ from verundentsorgung.st_dokument 
  where bemerkung = 'periodischer temporärer Import durch Job';
raise notice '%', concat('Es werden ', vZ::text, ' DS aus verundentsorgung.st_dokument gelöscht');
--
if vexecute = '1' then
  delete from verundentsorgung.st_dokument where bemerkung = 'periodischer temporärer Import durch Job';
end if; --if vexecute = '1' then
--
--
--
select count(*) into vZ from (
select u.id::uuid id
    , 'periodischer temporärer Import durch Job' bemerkung 
    , h.id::text    id_objekt  
    , h.name_number ident_hist
    , h.name_number ident_object_hist
    , concat(u.befahrungstag, ', ', u.dateiname)   titel
    , 'periodischer temporärer Import durch Job'   kommentar
    , u.dateiname datei
    , (select i.id from verundentsorgung.st_vw_dokumenttyp i where i.langtext = u.mimetyp) id_st_vw_dokumenttyp
    , 'kowa_leitungbestand_zvg' id_projekt
    , u.dateiname datei_name
    , u.dateipfad datei_pfad
    , u.mimetyp datei_mimetyp
    , 'verundentsorgung' objekt_tabelle_schema
  from (
        select a.* from (select id, id_st_vw_projekt, name_number, 'application/pdf' mimetyp, concat(befahrungsjahr,'-',befahrungsmonat,'-',befahrungstag) befahrungstag, dateiname, concat('/dokumente/ARCHIV/ISYBAU/PROTOKOLLE_PDF/REVISION03','/',dateiname) dateipfad 
          from verundentsorgung.fremd_zvg_isybau_dateinamen_v_mv ) a
      union 
        select a.* from (select id, id_st_vw_projekt, name_number, 'image/jpeg' mimetyp, substring(metadaten,1,10) befahrungstag, dateiname, replace(dateipfad, '/mnt/dokumente/O', '/dokumente/O') dateipfad 
          from verundentsorgung.fremd_zvg_isybau_bilder_und_videos_v_mv where dateiname like '%jpg' ) a
      union 
        select a.* from (select id, id_st_vw_projekt, name_number, 'video/mp4'  mimetyp, substring(metadaten,1,10) befahrungstag, dateiname, replace(dateipfad, '/mnt/dokumente/O', '/dokumente/O') dateipfad
          from verundentsorgung.fremd_zvg_isybau_bilder_und_videos_v_mv where dateiname like '%mp4' ) a
        ) u, verundentsorgung.aw_lin_haltung_v h 
  where u.name_number = h.name_number 
    and u.id_st_vw_projekt::uuid = h.id_st_vw_projekt::uuid 
    and not exists ( select 'X' from verundentsorgung.st_dokument i where i.id_objekt::text = h.id::text and upper(i.datei) = upper(u.dateipfad) )
order by mimetyp
) A;
raise notice '%', concat('Es werden ', vZ::text, ' DS in verundentsorgung.st_dokument geschrieben');
--
if vexecute = '1' then
insert into verundentsorgung.st_dokument
(
    id
  , bemerkung
  , id_objekt
  , ident_hist
  , ident_object_hist
  , titel
  , kommentar
  , datei
  , id_vw_dokumenttyp
  , id_projekt, datei_name
  , datei_pfad
  , datei_mimetyp
--, datei_inhalt
  , objekt_tabelle_schema
)
select u.id::uuid id
    , 'periodischer temporärer Import durch Job' bemerkung 
    , h.id::text    id_objekt  
    , h.name_number ident_hist
    , h.name_number ident_object_hist
    , concat(u.befahrungstag, ', ', u.dateiname)   titel
    , 'periodischer temporärer Import durch Job'   kommentar
    , u.dateiname datei
    , (select i.id from verundentsorgung.st_vw_dokumenttyp i where i.langtext = u.mimetyp) id_vw_dokumenttyp
    , 'kowa_leitungbestand_zvg' id_projekt
    , u.dateiname datei_name
    , u.dateipfad datei_pfad
    , u.mimetyp datei_mimetyp
    , 'verundentsorgung' objekt_tabelle_schema
  from (
        select a.* from (select id, id_st_vw_projekt, name_number, 'application/pdf' mimetyp, concat(befahrungsjahr,'-',befahrungsmonat,'-',befahrungstag) befahrungstag, dateiname, concat('/dokumente/ARCHIV/ISYBAU/PROTOKOLLE_PDF/REVISION03','/',dateiname) dateipfad 
          from verundentsorgung.fremd_zvg_isybau_dateinamen_v_mv ) a
      union 
        select a.* from (select id, id_st_vw_projekt, name_number, 'image/jpeg' mimetyp, substring(metadaten,1,10) befahrungstag, dateiname, replace(dateipfad, '/mnt/dokumente/O', '/dokumente/O') dateipfad 
          from verundentsorgung.fremd_zvg_isybau_bilder_und_videos_v_mv where dateiname like '%jpg' ) a
      union 
        select a.* from (select id, id_st_vw_projekt, name_number, 'video/mp4'  mimetyp, substring(metadaten,1,10) befahrungstag, dateiname, replace(dateipfad, '/mnt/dokumente/O', '/dokumente/O') dateipfad
          from verundentsorgung.fremd_zvg_isybau_bilder_und_videos_v_mv where dateiname like '%mp4' ) a
        ) u, verundentsorgung.aw_lin_haltung_v h 
  where u.name_number = h.name_number 
    and u.id_st_vw_projekt::uuid = h.id_st_vw_projekt::uuid  
    and not exists ( select 'X' from verundentsorgung.st_dokument i where i.id_objekt::text = h.id::text and upper(i.datei) = upper(u.dateipfad) )
order by mimetyp
; --31604
end if; --if vexecute = '1' then
--
--select count(*) from verundentsorgung.st_dokument2objekt where id_objekt::uuid in (select id::uuid from verundentsorgung.aw_pkt_schacht_v); --26671
--select count(*) from verundentsorgung.st_dokument2objekt where id_objekt::uuid in (select id::uuid from verundentsorgung.aw_lin_haltung_v); --0
--select id from verundentsorgung.aw_lin_haltung_v where id = '74117083-a9bb-4fa5-801f-4e795dceff0a';
--
select count(*) into vZ from (
select 
  h.id id_objekt
, d.id id_dokument
, 'verundentsorgung' objekt_tabelle_schema
, 'verundentsorgung' objekt_tabelle
, 'kowa_leitungbestand_zvg' id_projekt
, 'periodischer temporärer Import durch Job' angelegt_von
, 'periodischer temporärer Import durch Job' geaendert_von
 from 
   verundentsorgung.dokument d
 , verundentsorgung.aw_lin_haltung_v h 
  where d.bemerkung   = 'periodischer temporärer Import durch Job' 
   and  d.id_objekt::uuid   = h.id::uuid
   --and  d.id_st_vw_projekt   = h.id_st_vw_projekt
   and (h.id, d.id) not in (select id_objekt, id_dokument from verundentsorgung.st_dokument2objekt)
) A;
raise notice '%', concat('Es werden ', vZ::text, ' DS in verundentsorgung.st_dokument2objekt geschrieben');
if vexecute = '1' then
insert into verundentsorgung.st_dokument2objekt (
  id_objekt
, id_dokument
, objekt_tabelle_schema
, objekt_tabelle
, id_projekt
, angelegt_von
, geaendert_von
)
select 
  h.id id_objekt
, d.id id_dokument
, 'verundentsorgung' objekt_tabelle_schema
, 'verundentsorgung' objekt_tabelle
, 'kowa_leitungbestand_zvg' id_projekt
, 'periodischer temporärer Import durch Job' angelegt_von
, 'periodischer temporärer Import durch Job' geaendert_von
 from 
   verundentsorgung.dokument d
 , verundentsorgung.aw_lin_haltung_v h 
  where d.bemerkung   = 'periodischer temporärer Import durch Job' 
   and  d.id_objekt   = h.id
   --and  d.id_st_vw_projekt   = h.id_st_vw_projekt
   and not exists ( select 'X' from verundentsorgung.st_dokument2objekt i where i.id_objekt = h.id and i.id_dokument = d.id  )
 ;
end if; --if vexecute = '1' then
end if; --if vtabellenpraefix = 'isybaudokumente' and vmandant = 'zvg' then
END;
$$;


