CREATE FUNCTION verundentsorgung.admin_layerstruktur2admin_symbole_mv_refresh(vtable_schema text, vid_st_vw_projekt uuid, vnotice text, vexecute text) RETURNS text
    LANGUAGE plpgsql
    AS $_$
declare
vZ       integer default 0;
vSQL     text;
vRETURN  text default '1';
vst_vw_projekt_kurztext text;
--
  verror_state      text;
  verror_text       text;
  verror_detail     text;
  verror_hint       text;
  verror_context    text;
--
--select verundentsorgung.admin_layerstruktur2admin_symbole_mv_refresh ('verundentsorgung', '00000000-0000-0000-0000-000000000001'::uuid, '1', '1');
--
--
begin
vSQL := 'select kurztext from "'||vtable_schema||'".st_vw_projekt where id = $1'; if vNOTICE  = '1' then raise notice '%', vSQL; end if; if vEXECUTE = '1' then execute vSQL into vst_vw_projekt_kurztext using vid_st_vw_projekt; end if;
vSQL := 'create table if not exists "'||vtable_schema||'"."admin_layerstruktur2admin_symbole_mv" as select * from "'||vtable_schema||'"."admin_layerstruktur2admin_symbole" where 1 = 2'; if vNOTICE  = '1' then raise notice '%', vSQL; end if; if vEXECUTE = '1' then execute vSQL; end if;
vSQL := 'delete from "'||vtable_schema||'"."admin_layerstruktur2admin_symbole_mv" where projekt = $1'; if vNOTICE  = '1' then raise notice '%', vSQL; end if; if vEXECUTE = '1' then execute vSQL using vst_vw_projekt_kurztext; end if;
vSQL := 'insert into "'||vtable_schema||'"."admin_layerstruktur2admin_symbole_mv" select * from "'||vtable_schema||'"."admin_layerstruktur2admin_symbole" where projekt = $1 order by case when symbol_objektklasse like ''%lin%'' then line_style else pkt_symbol_size end '; if vNOTICE  = '1' then raise notice '%', vSQL; end if; if vEXECUTE = '1' then execute vSQL using vst_vw_projekt_kurztext; end if;
--vacuum full verundentsorgung.admin_layerstruktur2admin_symbole_mv;
vSQL := 'analyze "'||vtable_schema||'".admin_layerstruktur2admin_symbole_mv'; if vNOTICE  = '1' then raise notice '%', vSQL; end if; if vEXECUTE = '1' then execute vSQL; end if;
return vRETURN;
