            ''''::text AS symbol_objekttyp,
            ''''::text AS symbolname_alt,
            l.zeile
           FROM "'||vtable_schema||'".admin_layerstruktur l
          GROUP BY l.projekt, l.medium, l.objekttyp, l.objektklasse, l.symbol
