 where projekt = $2 order by case when symbol_objektklasse like ''%lin%'' then line_style else pkt_symbol_size end '; if vNOTICE  = '1' then raise notice '%', vSQL; end if; if vEXECUTE = '1' then execute vSQL using vid_st_vw_projekt, vst_vw_projekt_kurztext; end if;
