                 , l.pkt_symbol_angle, l.medium_gruppe, l.zeile) a
;
*/
EXCEPTION
  WHEN OTHERS THEN
  GET STACKED DIAGNOSTICS 
    verror_state  = RETURNED_SQLSTATE,
    verror_text   = MESSAGE_TEXT,
    verror_detail = PG_EXCEPTION_DETAIL,
    verror_hint   = PG_EXCEPTION_HINT,
    verror_context= PG_EXCEPTION_CONTEXT;
    --PERFORM verundentsorgung.f_admin_error_log( verror_state, verror_text, verror_detail, verror_hint, verror_context, 'admin_layerstruktur2st_vw_kartenlayout', vid_st_vw_projekt );
RAISE;
end; $_$;


--
