CREATE FUNCTION verundentsorgung.admin_layout_return(vrueckgabeformat text, vtable_schema text, vtable_name text, vid_st_vw_projekt uuid, vid_st_vw_betriebsstatus uuid, vid_st_vw_eigentuemer uuid, vid_st_vw_betreiber uuid, vid_st_vw_medium uuid, vid_st_vw_lagestatus uuid, vid_st_vw_material uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $_$
declare
vRETURN text default '1';
vSQL text;
vsymbolname text;
vtyp_id uuid;
vMedium text;
vrec text;
begin
--raise notice 'layout start';
--raise notice '%',vtyp_id;
vsql := 'select symbolname from verundentsorgung.st_vw_kurztext_langtext_alle where id = $1';
execute vsql into vsymbolname using vid_st_vw_material;
raise notice '%',vsymbolname;

if vtable_name = 'aw_pkt_fliessrichtungspfeil' then vsymbolname = 'RIPFEIDR'; end if ;
if vtable_name = 'wa_pkt_beprobungspunkt' then vsymbolname = 'NK'; end if ;
if vtable_name like 'ka_%' then vMedium = 'st_vw_verwendung'; ELSIF   vtable_name like 'ta_%' then vMedium = 'st_vw_verwendung'; else vMedium = 'st_vw_medium'; end if ;
--raise notice '%', vMedium;

if vtable_name like 'ta_%' then vid_st_vw_lagestatus = 'fe4a5552-29ea-443a-bdd2-14551378ce85' ; end if;
if vtable_name = 'aw_lin_schutzrohr' and vid_st_vw_projekt = '00000000-0000-0000-0000-000000000001' then vid_st_vw_medium = '679a1c1e-9020-4d25-9547-6e627802e46b' ; end if;
if vtable_name = 'wa_lin_schutzrohr' and vid_st_vw_projekt = '00000000-0000-0000-0000-000000000001' then vid_st_vw_medium = 'e7930a5a-2457-4acc-8170-7572899a9f8a' ; end if;
if vtable_name = 'ta_lin_schutzrohr' and vid_st_vw_projekt = '00000000-0000-0000-0000-000000000001' then vid_st_vw_medium = '7e3b5087-3f4a-4ffa-9b7d-854fe547d504' ; end if;
if vtable_name = 'ta_pkt_schutzrohr' and vid_st_vw_projekt = '00000000-0000-0000-0000-000000000001' then vid_st_vw_medium = '7e3b5087-3f4a-4ffa-9b7d-854fe547d504' ; end if;

if vtable_name = 'aw_lin_schutzrohr' and vid_st_vw_projekt = '00000000-0000-0000-0000-000000000003' then vid_st_vw_medium = '260db7b2-ba4a-4e61-b16f-cf8db17d36b8' ; end if;

--select verundentsorgung.admin_layerstruktur2admin_symbole_mv_refresh ('verundentsorgung', '00000000-0000-0000-0000-000000000001'::uuid, '1', '1');
--
--raise notice '%',vid_st_vw_medium;

/* 
select verundentsorgung.admin_layout_return (
  'array'
, 'verundentsorgung' --vTABLE_SCHEMA text
, 'aw_lin_haltung'   --vTABLE_NAME text
, id_st_vw_projekt
, id_st_vw_betriebsstatus
, id_st_vw_eigentuemer
, id_st_vw_betreiber
, id_st_vw_medium
, id_st_vw_lagestatus
, id_st_vw_material) from verundentsorgung.aw_lin_haltung where name_number = 'A1005S1030'
;
*/
if '1' = '1' then
if upper(vRUECKGABEFORMAT) = 'ARRAY' then
vSQL := 'select concat( ''excelzaehler_01'','', '',''''||zeile||'''' ,'', '',
                        ''hex_farbe_03'','', '',''''||hex_farbe||'''' ,'', '',
                        ''strichstaerke_mm_05'','', '',''''||strichstaerke_mm||'''' ,'', '',
                        ''line_style_07'','', '',''''||line_style||'''' ,'', '',
                        ''hex_line_color_09'','', '',''''||hex_line_color||'''' ,'', '',
                        ''line_alpha_11'','', '',''''||line_alpha||'''' ,'', '',
                        ''line_width_13'','', '',''''||line_width||'''' ,'', '',
                        ''line_width_unit_15'','', '',''''||line_width_unit||'''' ,'', '',
                        ''pkt_symbolname_17'','', '',''''||pkt_symbolname||'''' ,'', '',
                        ''pkt_symbolnamelang_19'','', '',''''||pkt_symbolnamelang||'''' ,'', '',
                        ''hex_pkt_stroke_color_21'','', '',''''||hex_pkt_stroke_color||'''' ,'', '',
                        ''pkt_fill_color_23'','', '',''''||pkt_fill_color||'''' ,'', '',
                        ''hex_pkt_fill_color_25'','', '',''''||hex_pkt_fill_color||'''' ,'', '',
                        ''pkt_stroke_with_27'','', '',''''||pkt_stroke_with||'''' ,'', '',
                        ''hex_pkt_stroke_color_29'','', '',''''||hex_pkt_stroke_color||'''' ,'', '',
                        ''pkt_symbol_angle_31'','', '',''''||pkt_symbol_angle||''''
                      ) from (
          SELECT --l.ogc_fid,l.zeile, 
	l.projekt, l.medium, l.objekttyp, l.objektklasse, l.symbol --, l.medium_filter_alt
                                 , l.medium_filter
                                 , l.betriebsstatus_filter, l.lagestatus_filter, l.eigentuemer_filter, l.betreiber_filter
                                 , l.darstellung
                                 , l.rgb_farbe
                                 , '||vTABLE_SCHEMA||'.rgb_to_hex( l.rgb_farbe ) hex_farbe
                                 , l.strichstaerke_mm
                                 , l.line_style
                                 , l.line_color
                                 , '||vTABLE_SCHEMA||'.rgb_to_hex( l.line_color ) hex_line_color
                                 , l.line_alpha
                                 , l.line_width
                                 , l.line_width_unit
                                 , l.symbolname as pkt_symbolname
                                 , l.pkt_symbolnamelang
                                 , l.pkt_stroke_color
                                 , '||vTABLE_SCHEMA||'.rgb_to_hex( l.pkt_stroke_color ) hex_pkt_stroke_color
                                 , l.pkt_fill_color
                                 , '||vTABLE_SCHEMA||'.rgb_to_hex( l.pkt_fill_color ) hex_pkt_fill_color
                                 , l.pkt_stroke_with
                                 , l.pkt_symbol_size
                                 , l.pkt_symbol_angle
                                 , betrst.kurztext betriebsstatus_kurztext, /*eig.kurztext eigentuemer_kurztext,*/ betrei.kurztext betreiber_kurztext, med.kurztext medium_kurztext, last.kurztext lagestatus_kurztext
                                 , betrst.langtext betriebsstatus_langtext, /*eig.langtext eigentuemer_langtext,*/ betrei.langtext betreiber_langtext, med.langtext medium_langtext, last.langtext lagestatus_langtext
                                 ,case when $6 is null then l.symbolname else $6  end as symbolname
								 , l.zeile
							   FROM '||vTABLE_SCHEMA||'.admin_layerstruktur2admin_symbole  l	
							   --FROM '||vTABLE_SCHEMA||'.st_vw_kartenlayout                    l	
                                  , '||vTABLE_SCHEMA||'.st_vw_projekt        p 
                                  , '||vTABLE_SCHEMA||'.st_vw_betriebsstatus betrst
                                  , '||vTABLE_SCHEMA||'.st_vw_eigentuemer    eig
                                  , '||vTABLE_SCHEMA||'.st_vw_betreiber      betrei
                                  , '||vTABLE_SCHEMA||'.st_vw_medium         med
                                  , '||vTABLE_SCHEMA||'.st_vw_lagestatus     last 
                                  --, '||vTABLE_SCHEMA||'.aw_lin_haltung       dummy
                               where p.id = $1 
                                 --and p.kurztext = l.projekt 
								 and l.darstellung = ''zulaessig'' and	
								 l.symbol_objektklasse =   '''||vTABLE_NAME||'''	
                                 and p.id = betrst.id_st_vw_projekt and betrst.id = $2 --upper(betrst.kurztext) = upper(''ib'')
                                 and p.id = eig.id_st_vw_projekt    and eig.id    = $7    --upper(eig.kurztext)    = upper(''GEMEINDE'')
                                 and p.id = betrei.id_st_vw_projekt and betrei.id = $3      --upper(betrei.kurztext) = upper(''ZVG'')
                                 and p.id = med.id_st_vw_projekt    and med.id    = $4         --upper(med.kurztext)    = upper(''KS_TRL'')
                                 and p.id = last.id_st_vw_projekt   and last.id   = $5     --upper(last.kurztext)   = upper(''LS'')
                                 --
                                 and upper(  case when upper(betrst.kurztext) in (''IB'', ''INBETRIEB'') then ''IB'' when upper(betrst.kurztext) in (''ZG'', ''ZURUECK GEBAUT'') then ''ZG''  when upper(betrst.kurztext) in (''STGE'', ''stillgelegt'') then ''SG''  else ''AB'' end ) = ( upper( case when upper(l.betriebsstatus_filter) = ''IB'' then ''IB'' when upper(l.betriebsstatus_filter) = ''ZG'' then ''ZG'' when upper(l.betriebsstatus_filter) = ''SG'' then ''SG'' else ''AB'' end ))
                                 and position(upper(case when eig.kurztext    = ''ZVG'' then ''Z'' when eig.kurztext    = ''ZVG_GEMEINDE'' then ''Z''  when eig.kurztext    = ''ZVG_LK'' then ''Z''  when eig.kurztext    = ''ZVG_SBA'' then ''Z'' else ''U'' end) in upper(l.eigentuemer_filter))    > 0 --Z
                                 and upper(case when betrei.kurztext = ''ZVG'' then ''Z'' else ''U'' end) = upper(l.betreiber_filter) --Z
                                 and position(upper(med.kurztext)    in upper(l.medium_filter))         > 0
                                 and upper(case when upper(last.kurztext) in ( ''LAGESICHER'', ''LS'' ) then ''LS'' else ''LU'' end ) = upper( case when upper(l.lagestatus_filter) in ( ''LS'' ) then ''LS'' else ''LU'' end )                                 
                                 --
                                 --and p.id = dummy.id_st_vw_projekt and dummy.name_number = ''A1005S1030''
                                 --and upper(l.medium)    = upper(''WW'')
                                 --and upper(l.objekttyp) = upper(''GEOM'')
								 --order by case when l.symbol_objektklasse like ''%lin%'' then l.line_style else l.pkt_symbol_size end 				
                                ) A limit 1
                               ';
end if; --if upper(vRUECKGABEFORMAT) = 'ARRAY' then
if upper(vRUECKGABEFORMAT) = 'JSONB' then
--raise notice 'JSON';
vSQL := 'select jsonb_strip_nulls(
					jsonb_build_object( 
						--''excelzaehler'',zeile,
                        ''farbe'',hex_farbe ,
                        ''strichstaerke'',strichstaerke_mm,
                        ''line_style'',line_style ,
                        ''hex_line_color'',hex_line_color,
                        ''line_alpha'',line_alpha,
                        ''line_width'',line_width ,
                        ''line_width_unit'',line_width_unit ,
                        ''pkt_symbolname'',symbolname ,                        
						''pkt_symbolnamelang'',pkt_symbolnamelang ,
                        ''hex_pkt_stroke_color'',hex_pkt_stroke_color ,
                        ''pkt_fill_color'',pkt_fill_color ,
                        ''hex_pkt_fill_color'',hex_pkt_fill_color ,
                        ''pkt_stroke_with'',pkt_stroke_with ,
                        ''hex_pkt_stroke_color'',hex_pkt_stroke_color ,
                        ''pkt_symbol_angle'',pkt_symbol_angle,
						''admin_layerstruktur'',ogc_fid,
						''medium_kurztext'',medium_s,
						''betriebsstatus_kurztext'',betriebsstatus_kurztext_2,
						''betreiber_kurztext'',betreiber_kurztext_2,
						''table_name'',tabellen_name
                      )) from (
          SELECT l.ogc_fid,--l.zeile, 
	l.projekt, l.medium, l.objekttyp, l.objektklasse, l.symbol --, l.medium_filter_alt
                                 , l.medium_filter
                                 , l.betriebsstatus_filter, l.lagestatus_filter, l.eigentuemer_filter, l.betreiber_filter
                                 , l.darstellung
                                 , l.rgb_farbe
                                 ,  l.rgb_farbe  hex_farbe
                                 , l.strichstaerke_mm
                                 , l.line_style
                                 , l.line_color
                                 , l.line_color  hex_line_color
                                 , l.line_alpha
                                 , l.line_width
                                 , l.line_width_unit
                                 , l.symbolname as pkt_symbolname
                                 , l.pkt_symbolnamelang
                                 , l.pkt_stroke_color
                                 ,  l.pkt_stroke_color  hex_pkt_stroke_color
                                 , l.pkt_fill_color
                                 ,  l.pkt_fill_color  hex_pkt_fill_color
                                 , l.pkt_stroke_with
                                 , l.pkt_symbol_size
                                 , l.pkt_symbol_angle
                                 , betrst.kurztext betriebsstatus_kurztext, /*eig.kurztext eigentuemer_kurztext,*/ betrei.kurztext betreiber_kurztext, med.kurztext medium_kurztext, last.kurztext lagestatus_kurztext
                                 , betrst.langtext betriebsstatus_langtext, /*eig.langtext eigentuemer_langtext,*/ betrei.langtext betreiber_langtext, med.langtext medium_langtext, last.langtext lagestatus_langtext
                                 ,case when $6 is null then l.symbolname else $6  end as symbolname
								 , l.zeile
								 ,med.kurztext as medium_s
								 ,'''||vTABLE_NAME||''' as tabellen_name
								 ,betrst.kurztext as betriebsstatus_kurztext_2
								 ,betrei.kurztext as betreiber_kurztext_2
							   --FROM '||vTABLE_SCHEMA||'.admin_layerstruktur2admin_symbole  l	
							   FROM '||vTABLE_SCHEMA||'.admin_layerstruktur2admin_symbole_mv  l
							   --FROM '||vTABLE_SCHEMA||'.st_vw_kartenlayout                    l	
                                  , '||vTABLE_SCHEMA||'.st_vw_projekt        p 
                                  , '||vTABLE_SCHEMA||'.st_vw_betriebsstatus betrst
                                  , '||vTABLE_SCHEMA||'.st_vw_eigentuemer    eig
                                  , '||vTABLE_SCHEMA||'.st_vw_betreiber      betrei
                                  , '||vTABLE_SCHEMA||'.'||vMedium||'         med
                                  , '||vTABLE_SCHEMA||'.st_vw_lagestatus     last 
                                  --, '||vTABLE_SCHEMA||'.aw_lin_haltung       dummy
                               where p.id = $1 
                                 --and p.kurztext = l.projekt and
								  and l.darstellung = ''zulaessig'' 	and 
								  l.symbol_objektklasse =   '''||vTABLE_NAME||'''	
                                 and p.id = betrst.id_st_vw_projekt and betrst.id = $2 --upper(betrst.kurztext) = upper(''ib'')
                                 and p.id = eig.id_st_vw_projekt    and eig.id    = $7    --upper(eig.kurztext)    = upper(''GEMEINDE'')
                                 and p.id = betrei.id_st_vw_projekt and betrei.id = $3      --upper(betrei.kurztext) = upper(''ZVG'')
                                 and p.id = med.id_st_vw_projekt     and med.id   = $4         --upper(med.kurztext)    = upper(''KS_TRL'')
                                 and p.id = last.id_st_vw_projekt   and last.id   = $5     --upper(last.kurztext)   = upper(''LS'')
                                 --
                                -- and upper(  case when upper(betrst.kurztext) in (''IB'', ''INBETRIEB'') then ''IB'' when upper(betrst.kurztext) in (''ZG'', ''ZURUECK GEBAUT'') then ''ZG''  when upper(betrst.kurztext) in (''STGE'', ''stillgelegt'') then ''SG''  else ''AB'' end ) = ( upper( case when upper(l.betriebsstatus_filter) = ''IB'' then ''IB'' when upper(l.betriebsstatus_filter) = ''ZG'' then ''ZG'' when upper(l.betriebsstatus_filter) = ''SG'' then ''SG'' else ''AB'' end ))
                                 and upper(  case when upper(betrst.kurztext) in (''IB'', ''INBETRIEB'') then ''IB''
                                 				  when upper(betrst.kurztext) in (''ZG'', ''ZURUECK GEBAUT'') then ''ZG'' 
                                 				  when upper(betrst.kurztext) in (''STGE'', ''stillgelegt'') then ''SG''  
                                 				  when upper(betrst.kurztext) in (''GPL'') then ''GPL''  
                                 				  else ''AB'' end ) 
                                 			= 
                                 	( upper( case when upper(l.betriebsstatus_filter) = ''IB'' then ''IB'' 
                                 				  when upper(l.betriebsstatus_filter) = ''ZG'' then ''ZG'' 
                                 				  when upper(l.betriebsstatus_filter) = ''SG'' then ''SG'' 
                                 				  when upper(l.betriebsstatus_filter) = ''GPL'' then ''GPL''  
                                 				  else ''AB'' end )) 
								and position(upper(case when eig.kurztext    = ''ZVG'' then ''Z'' 
														when eig.kurztext    = ''ZKWAL'' then ''Z'' 			
														when eig.kurztext    = ''ZVG_GEMEINDE'' then ''Z'' 
														when eig.kurztext 	 = ''GEMEINDE'' then ''U''   
														when eig.kurztext    = ''ZVG_LK'' then ''Z'' 
														when eig.kurztext    = ''ZVWIS'' then ''Z'' 
														when eig.kurztext    = ''ZVG_SBA'' 
														then ''Z'' else ''U'' end) in upper(l.eigentuemer_filter))    > 0 --Z
                                 and upper(case when betrei.kurztext = ''ZVG''	then ''Z''  when betrei.kurztext    = ''ZVWIS'' then ''Z'' when betrei.kurztext    = ''ZKWAL'' then ''Z'' else ''U'' 														end) = upper(l.betreiber_filter) --Z
                                 and position(upper(med.kurztext)    in upper(l.medium_filter))         > 0
                                 and upper(case when upper(last.kurztext) in ( ''LAGESICHER'', ''LS'' ) then ''LS'' else ''LU'' end ) = upper( case when upper(l.lagestatus_filter) in ( ''LS'' ) then ''LS'' else ''LU'' end )                                 				
                                ) A limit 1
                               ';

end if; --if upper(vRUECKGABEFORMAT) = 'ARRAY' then
        execute vSQL into vRETURN using vid_st_vw_projekt, vid_st_vw_betriebsstatus, vid_st_vw_betreiber, vid_st_vw_medium, vid_st_vw_lagestatus, vsymbolname, vid_st_vw_eigentuemer;
raise notice '%,%,%,%,%,%,%,%',vid_st_vw_projekt, vid_st_vw_betriebsstatus, vid_st_vw_betreiber, vid_st_vw_medium, vid_st_vw_lagestatus, vsymbolname, vid_st_vw_eigentuemer,vid_st_vw_material;
--raise notice '%', vRETURN;
end if; --if '1' = '1' then



if 1=0 then
FOR vrec IN
    EXECUTE 'EXPLAIN (ANALYZE, BUFFERS) ' || vSQL
    USING vid_st_vw_projekt,
          vid_st_vw_betriebsstatus,
          vid_st_vw_betreiber,
          vid_st_vw_medium,
          vid_st_vw_lagestatus,
          vsymbolname,
          vid_st_vw_eigentuemer
LOOP
    --RAISE NOTICE '%', vrec;
END LOOP;
end if;

--
--
--
RETURN vRETURN;
		END
$_$;


