                      ) from (
          SELECT l.ogc_fid, l.zeile, l.projekt, l.medium, l.objekttyp, l.objektklasse, l.symbol, l.medium_filter_alt, l.medium_filter
                                 , l.betriebsstatus_filter, l.lagestatus_filter, l.eigentuemer_filter, l.betreiber_filter
                                 , l.darstellung
                                 , l.rgb_farbe
                                 , '||vTABLE_SCHEMA||'.rgb_to_hex( l.rgb_farbe ) hex_farbe
                                 , l.strichstaerke_mm
                                 , l.line_style
                                 , l.line_color
                                 , '||vTABLE_SCHEMA||'.rgb_to_hex( l.line_color ) hex_line_color
                                 , l.line_alpha
                                 , l.line_width
