select '1' wert_aktivstatus_historie, '0' wert_aktivstatus, '1' wert_erfassung, 'db_benutzer' kurztext, 'wenn wert_aktivstatus = 1 wird der Datenbankbenutzer in angelegt_von und geaendert_von geschrieben.' bemerkung union
