) loop
if vPARAMETER = 'neusetzen'     then vSQL := 'update verundentsorgung.admin_projekt_parameter set wert_aktivstatus = '''||vRC.wert_aktivstatus||'''          where kurztext = '''||vRC.kurztext||''' and id_st_vw_projekt = ''00000000-0000-0000-0000-000000000001'' '; if vNOTICE = '1' then raise notice '%', vSQL; end if; if vEXECUTE = '1' then execute vSQL; end if; end if;
