CREATE FUNCTION verundentsorgung.admin_select_admin_projekt_parameter(vkurztext text, vid_st_vw_projekt text, OUT vnotiz text, OUT vfehlermeldung text, OUT vwert_numerisch numeric, OUT vwert_text text, OUT vwert_timestamptz timestamp with time zone, OUT vwert_aktivstatus text) RETURNS record
    LANGUAGE plpgsql
    AS $_$
declare
vSQL text;
begin
--select verundentsorgung.admin_select_admin_projekt_parameter('historie, '00000000-0000-0000-0000-000000000001');
vSQL := 'select 
     notiz::text,
     fehlermeldung::text,
     wert_numerisch::numeric,
     wert_text::text,
     wert_timestamptz::timestamptz,
     wert_aktivstatus::text
