/*select * from (
select table_schema, table_name, 
'alter table '||table_schema||'.'||table_name||' drop constraint uk1_'||table_name||'_kurztext;' s
from information_schema.tables where table_schema = 'verundentsorgung' and substr(table_name,1,5) in ( 'st_vw') and table_name not in ('st_vw_kartenlayout', 'st_vw_projekt') --order by 1,2
union 
select table_schema, table_name, 
'alter table '||table_schema||'.'||table_name||' drop constraint uk2_'||table_name||'_langtext;' s
