*/
begin
--
select id into vID_QUELLPROJEKT from verundentsorgung.st_vw_projekt where kurztext = vQUELLPROJEKT;
select id into vID_ZIELPROJEKT  from verundentsorgung.st_vw_projekt where kurztext = vZIELROJEKT;
