vSQL := 'select table_schema, table_name, (select count(*) A from information_schema.columns i where i.table_schema = t.table_schema and i.table_name = t.table_name ) anzahl_columns 
           from information_schema.tables t where 
           table_schema like ''verundentsorgung'' 
       and (table_schema, table_name) not in (select table_schema, table_name from information_schema.views) --keine Views
