       and (table_schema, table_name, ''ident_hist'') in (select table_schema, table_name, column_name from information_schema.columns)
       and substr(table_name,1,5) in ( ''st_vw'') and table_name not in (''st_vw_kartenlayout'', ''st_vw_projekt'') --order by 1,2 -- (''aw'',''wa'',''ka'',''st'') 
       and table_name like ('''||vquelltabelle||''')       
       order by 1,2
  ';
--
for vRC in execute vSQL loop
if vrc.anzahl_columns::int  > 0::int then
vZ1 := vZ1 + 1; raise notice '%', concat('-------------------', vZ1);
vSQL := 'select count(*) from '||vrc.table_schema||'.'||vrc.table_name||' where id_st_vw_projekt = '''||vID_QUELLPROJEKT::text||'''::uuid and ( kurztext, '''||vID_ZIELPROJEKT::text||'''::uuid ) not in ( select kurztext, id_st_vw_projekt from '||vrc.table_schema||'.'||vrc.table_name||' )' ;
raise notice '%', concat('--', vSQL::text); --execute vSQL using vgeometry;
execute vSQL into vz;
