  and ( ', '''', vID_ZIELPROJEKT::text, '''::uuid, ', 'kurztext ) not in (select id_st_vw_projekt, kurztext from ', vrc.table_schema, '.', vrc.table_name, ') '); 
raise notice '%', vSQL; if vEXECUTE = '1' then execute vSQL; end if;
--
elsif vrc.table_name = 'st_vw_layout_spalten' then
vSQL := concat(
'insert into ', vrc.table_schema, '.', vrc.table_name, 
