 , ' select kurztext, langtext, bemerkung, gueltig_von, gueltig_bis, angelegt_am, angelegt_von, geaendert_am, geaendert_von, sortierreihenfolge, ident_hist', ', ''', vID_ZIELPROJEKT::text,'''::uuid', ' from ', vrc.table_schema, '.', vrc.table_name, ' where id_st_vw_projekt = ''', vID_QUELLPROJEKT, '''::uuid
  and ( ', '''', vID_ZIELPROJEKT::text, '''::uuid, ', 'kurztext ) not in (select id_st_vw_projekt, kurztext from ', vrc.table_schema, '.', vrc.table_name, ') '); 
raise notice '%', vSQL; if vEXECUTE = '1' then execute vSQL; end if;
--
elsif vrc.table_name = 'st_vw_typ2objektklasse' then
vSQL := concat(
'insert into ', vrc.table_schema, '.', vrc.table_name, 
        ' ( ident_hist, kurztext, langtext, bemerkung, sortierreihenfolge, gueltig_von, gueltig_bis, angelegt_am, angelegt_von, geaendert_am, geaendert_von, table_schema, table_name, id_st_vw_projekt )'
 , ' select ident_hist, kurztext, langtext, bemerkung, sortierreihenfolge, gueltig_von, gueltig_bis, angelegt_am, angelegt_von, geaendert_am, geaendert_von, table_schema, table_name', ', ''', vID_ZIELPROJEKT::text,'''::uuid', ' from ', vrc.table_schema, '.', vrc.table_name, ' where id_st_vw_projekt = ''', vID_QUELLPROJEKT, '''::uuid
  and ( ', '''', vID_ZIELPROJEKT::text, '''::uuid, ', 'kurztext ) not in (select id_st_vw_projekt, kurztext from ', vrc.table_schema, '.', vrc.table_name, ') '); 
raise notice '%', vSQL; if vEXECUTE = '1' then execute vSQL; end if;
--
elsif vrc.table_name = 'st_vw_vorgangart' then
vSQL := concat(
'insert into ', vrc.table_schema, '.', vrc.table_name, 
        ' ( ident_hist, kurztext, langtext, bemerkung, sortierreihenfolge, gueltig_von, gueltig_bis, angelegt_am, angelegt_von, geaendert_am, geaendert_von, id_st_vw_objektbezeichnung, id_st_vw_projekt )'
 , ' select ident_hist, kurztext, langtext, bemerkung, sortierreihenfolge, gueltig_von, gueltig_bis, angelegt_am, angelegt_von, geaendert_am, geaendert_von, id_st_vw_objektbezeichnung', ', ''', vID_ZIELPROJEKT::text,'''::uuid', ' from ', vrc.table_schema, '.', vrc.table_name, ' where id_st_vw_projekt = ''', vID_QUELLPROJEKT, '''::uuid
  and ( ', '''', vID_ZIELPROJEKT::text, '''::uuid, ', 'kurztext ) not in (select id_st_vw_projekt, kurztext from ', vrc.table_schema, '.', vrc.table_name, ') '); 
raise notice '%', vSQL; if vEXECUTE = '1' then execute vSQL; end if;
--
