 , ' select ident_hist, kurztext, langtext, bemerkung, sortierreihenfolge', ', ''', vID_ZIELPROJEKT::text,'''::uuid, richtungspfeil, richtungspfeil_abstand, name_number_kennung', ' from ', vrc.table_schema, '.', vrc.table_name, ' where id_st_vw_projekt = ''', vID_QUELLPROJEKT, '''::uuid
  and ( ', '''', vID_ZIELPROJEKT::text, '''::uuid, ', 'kurztext ) not in (select id_st_vw_projekt, kurztext from ', vrc.table_schema, '.', vrc.table_name, ') '); 
 --execute vSQL using vgeometry;
raise notice '%', vSQL; if vEXECUTE = '1' then execute vSQL; end if;
--
else
vSQL := concat(
'insert into ', vrc.table_schema, '.', vrc.table_name, 
