vSQL := 'select count(*) from (
select * from (
SELECT 
  id_st_strasse
, amt, gemeinde, ort, strasse 
, id_st_vw_projekt, projekt_kurztext, projekt_langtext
, id_st_vw_abrechnung, abrechnung_kurztext, abrechnung_langtext
