--
-- TOC entry 28761 (class 1255 OID 56278291)
-- Name: admin_values2csv(character varying); Type: FUNCTION; Schema: verundentsorgung; Owner: -
--

CREATE FUNCTION verundentsorgung.admin_values2csv(vabfrage character varying) RETURNS character varying
    LANGUAGE plpgsql STRICT
    AS $$
declare
vRETURN   character varying;
vSQL      character varying;
rcTABLES  RECORD;
vZ        integer default 0;
begin
  --select distinct infrastruktur.admin_values2csv('infrastruktur', 'benutzer2benutzergruppe2projekt_v', 'projekt', 'anmeldename = ''USERerfassen''', 'projekt');
  vSQL := vabfrage;
  for rcTABLES in execute vSQL loop 
    vZ      := vZ + 1;
    if vZ = 1 then vRETURN := rcTABLES::TEXT; else vRETURN := vRETURN||','||rcTABLES::TEXT; end if; --execute vSQL into vRETURN using 'INFRASTRUKTUR', vanmeldename, vprojekt, vid_objekt;
  end loop;
vRETURN = replace(vRETURN,'"',''); vRETURN = replace(vRETURN,')',''); vRETURN = replace(vRETURN,'(','');
return vRETURN; 
end;
$$;


