--
-- TOC entry 28686 (class 1255 OID 51483594)
-- Name: dgm_interpolation(double precision, double precision); Type: FUNCTION; Schema: verundentsorgung; Owner: -
--

CREATE FUNCTION verundentsorgung.dgm_interpolation(px double precision, py double precision) RETURNS double precision
    LANGUAGE plpgsql STRICT
    AS $$
DECLARE
    z1 float8; --Z Koordinate
    z2 float8;
    z3 float8;
    z4 float8;
    a1 float8; --Abstand
    a2 float8;
    a3 float8;
    a4 float8;
    vRC record;
    vSQL text;
    vZ integer default 0;
--zum Interpolieren
    w_a1 float8;
    w_b1 float8;
    w_c1 float8;
    w_d1 float8;
    sum_weights float8;
    z float8; --Rückgabewert
BEGIN
    vSQL := 'select a.*, x-'||px||' xdiff, y-'||py||' ydiff from (
               select id, x, y, z, st_distance( t.geometry, ST_GeomFromText(''POINT('||px||' '||py||')'', 25833) ) abstand 
                 from dgm_nwm_2012.dgm5_nwm_2012 t
                   where st_intersects(t.geometry, st_buffer( ST_GeomFromText(''POINT('||px||' '||py||')'', 25833), SQRT(50) ) )
                     and st_distance( t.geometry, ST_GeomFromText(''POINT('||px||' '||py||')'', 25833) ) <= SQRT(50) 
                                                                      ) a 
                where abs(x-'||px||') < 5 and abs(y-'||py||') < 5 limit 4';
for vRC in execute vSQL loop
vZ := vZ + 1;
  if       vZ = 1 then z1 := vRC.z; a1 := vRC.abstand; 
    elseif vZ = 2 then z2 := vRC.z; a2 := vRC.abstand; 
    elseif vZ = 3 then z3 := vRC.z; a3 := vRC.abstand; 
    elseif vZ = 4 then z4 := vRC.z; a4 := vRC.abstand; 
  end if;
end loop;
--
-- Jetzt habe ich die Abstände zu den Punkten, in dessen Quadrat ich mich befinde unbd dessen Höhen
-- Jetzt kann ich mit diesen Angaben interpolieren.
--select dgm_nwm_2012.interpolieren_auf_abstand(a1, z1, a2, z2, a3, z3, a4, z4) into z;
    -- Falls ein Abstand 0 ist: exakten Wert zurückgeben (Y1 liegt genau auf diesem Punkt!)
    IF a1 = 0 THEN RETURN z1; END IF;
    IF a2 = 0 THEN RETURN z2; END IF;
    IF a3 = 0 THEN RETURN z3; END IF;
    IF a4 = 0 THEN RETURN z4; END IF;
    -- IDW mit p=2
    w_a1 := 1/(a1*a1);
    w_b1 := 1/(a2*a2);
    w_c1 := 1/(a3*a3);
    w_d1 := 1/(a4*a4);
    sum_weights := w_a1 + w_b1 + w_c1 + w_d1;
    --
    z := (w_a1*z1 + w_b1*z2 + w_c1*z3 + w_d1*z4) / sum_weights;
    RETURN z;
END;
$$;


--
-- TOC entry 29052 (class 1255 OID 71118120)
-- Name: epsg2googlemaps(text, text, text, text); Type: FUNCTION; Schema: verundentsorgung; Owner: -
--

CREATE FUNCTION verundentsorgung.epsg2googlemaps(vx text, vy text, vquellepsg text, vrueckgabe text) RETURNS text
    LANGUAGE plpgsql
    AS $$
DECLARE
    vX_wgs84  numeric;
    vY_wgs84  numeric;
    vX_final  text;
    vY_final  text;
    vRETURN   text := '0';
    
    -- Variablen für DMS Umrechnung
    vDeg_lat int; vMin_lat int; vSec_lat numeric; vHem_lat text;
    vDeg_lon int; vMin_lon int; vSec_lon numeric; vHem_lon text;
    vDMS_coords text;
BEGIN
    -- Validierung
    IF length(vx) > 7 AND length(vy) > 7 THEN
        
        -- 1. Transformation immer nach EPSG:4326 für Google Maps
        -- Wir ignorieren vzielepsg für Google-Links, da Google nur WGS84 versteht.
        SELECT 
            ST_X(ST_Transform(ST_GeomFromText('POINT(' || vx || ' ' || vy || ')', vquellepsg::integer), 4326::int)),
            ST_Y(ST_Transform(ST_GeomFromText('POINT(' || vx || ' ' || vy || ')', vquellepsg::integer), 4326::int))
        INTO vX_wgs84, vY_wgs84;

        -- 2. Berechnung des DMS-Formats für den /place/ Teil
        -- Latitude (Y)
        vDeg_lat := floor(abs(vY_wgs84));
        vMin_lat := floor((abs(vY_wgs84) - vDeg_lat) * 60);
        vSec_lat := round(((abs(vY_wgs84) - vDeg_lat) * 60 - vMin_lat) * 60, 1);
        vHem_lat := CASE WHEN vY_wgs84 >= 0 THEN 'N' ELSE 'S' END;

        -- Longitude (X)
        vDeg_lon := floor(abs(vX_wgs84));
        vMin_lon := floor((abs(vX_wgs84) - vDeg_lon) * 60);
        vSec_lon := round(((abs(vX_wgs84) - vDeg_lon) * 60 - vMin_lon) * 60, 1);
        vHem_lon := CASE WHEN vX_wgs84 >= 0 THEN 'E' ELSE 'W' END;

        -- DMS String bauen und URL-encoden (Grad: %C2%B0, Minute: %27, Sekunde: %22)
        vDMS_coords := concat(
            vDeg_lat, '%C2%B0', vMin_lat, '%27', vSec_lat, '%22', vHem_lat, 
            '+', 
            vDeg_lon, '%C2%B0', vMin_lon, '%27', vSec_lon, '%22', vHem_lon
        );

        -- 3. Link-Typ bestimmen
        IF vrueckgabe = 'googlekoordinaten' THEN
            --vRETURN := concat('https://www.google.com/maps/search/?api=1&query=', vY_wgs84, ',', vX_wgs84);
            vRETURN := concat( round(vY_wgs84, 6)::text, ', ', round(vX_wgs84, 6)::text );
            
        ELSIF vrueckgabe = 'googlemapplacelink' THEN
            -- Format: .../place/[DMS]/@[Lat],[Lon],[Zoom]m/data=...
            -- Wir nutzen 197m als Zoom/Höhe wie in deinem Beispiel
            vRETURN := concat(
                'https://www.google.de/maps/place/', vDMS_coords, 
                '/@', vY_wgs84, ',', vX_wgs84, ',197m/data=!3m1!1e3!4m2!3m1!1s0x0:0x0'
            );
        END IF;

    END IF; --IF length(vx) > 7 AND length(vy) > 7 THEN

    RETURN vRETURN;
END;
$$;


