    error_id_st_vw_projekt  )
   select p.vpid, p.vdatname, p.vapplication_name, p.vclient_addr, p.vclient_hostname, p.vclient_port, p.vbackend_type
        , e.verror_state, e.verror_text, e.verror_detail, e.verror_hint, e.verror_context, e.verror_bemerkung, e.vid_st_vw_projekt
 --    from (select pid::text pid, datname, application_name, client_addr, client_hostname, client_port, backend_type from pg_stat_activity where pid = $1 ) p,
       from (select $1 vpid, $2 vdatname, $3 vapplication_name, $4 vclient_addr, $5 vclient_hostname, $6 vclient_port, $7 vbackend_type ) p,
 --         (select $2 error_state, $3 error_text,  $4 error_detail,  $5 error_hint,  $6 error_context,  $7 error_bemerkung,  $8 id_st_vw_projekt ) e 
            (select $8 verror_state, $9 verror_text, $10 verror_detail, $11 verror_hint, $12 verror_context, $13 verror_bemerkung, $14 vid_st_vw_projekt ) e 
';
-- nicht mehr aktuellexecute vSQL using pg_backend_pid(), verror_state, verror_text, verror_detail, verror_hint, verror_context, verror_bemerkung, vid_st_vw_projekt; 
--execute vSQL using vpid, vdatname, vapplication_name, vclient_addr, vclient_hostname, vclient_port, vbackend_type, verror_state, verror_text, verror_detail, verror_hint, verror_context, verror_bemerkung, vid_st_vw_projekt; 
vSQL := format('
  INSERT INTO '||vSCHEMA_NAME||'.admin_error_log (
    error_pid               ,
    error_datname           ,
    error_application_name  ,
    error_client_addr       ,
    error_client_hostname   ,
    error_client_port       ,
    error_backend_type      ,
    error_state             ,
    error_message           , 
    error_detail            , 
    error_hint              ,
    error_context           ,
    error_bemerkung         ,
    error_id_st_vw_projekt  )
   select p.vpid, p.vdatname, p.vapplication_name, p.vclient_addr, p.vclient_hostname, p.vclient_port, p.vbackend_type
        , e.verror_state, e.verror_text, e.verror_detail, e.verror_hint, e.verror_context, e.verror_bemerkung, e.vid_st_vw_projekt
       from (select %L vpid, %L vdatname, %L vapplication_name, %L vclient_addr, %L vclient_hostname, %L vclient_port, %L vbackend_type ) p,
            (select %L verror_state, %L verror_text, %L verror_detail, %L verror_hint, %L verror_context, %L verror_bemerkung, %L vid_st_vw_projekt ) e 
', vpid, vdatname, vapplication_name, vclient_addr, vclient_hostname, vclient_port, vbackend_type, verror_state, verror_text, verror_detail, verror_hint, verror_context, verror_bemerkung, vid_st_vw_projekt);
PERFORM dblink_exec('dblink_fdw_localhost_gis_verundentsorgung', vSQL);
--
if vNOTICE = '1' then raise notice '%','Trace02'; end if;
end if; --if vwert_aktivstatus = 1 then
if vNOTICE = '1' then raise notice ' % % % % % % % % ', verror_state, verror_text, verror_detail, verror_hint, verror_context, verror_bemerkung, vid_st_vw_projekt, pg_backend_pid()::text; end if;
END;
