--
-- TOC entry 28682 (class 1255 OID 49895319)
-- Name: id2value(uuid, uuid, text, text); Type: FUNCTION; Schema: verundentsorgung; Owner: -
--

CREATE FUNCTION verundentsorgung.id2value(vid uuid, vid_st_vw_projekt uuid, vtable_schema text, vrueckgabe text) RETURNS text
    LANGUAGE plpgsql
    AS $_$
declare
vSQL text;
vRC record;
vZ  integer;
vRETURN  text;
begin
/*
select 
    verundentsorgung.id2value (id, id_st_vw_projekt, 'verundentsorgung', 'table_name')  table_name
  , verundentsorgung.id2value (id, id_st_vw_projekt, 'verundentsorgung', 'name_number') name_number
  , verundentsorgung.id2value (id, id_st_vw_projekt, 'verundentsorgung', 'id_st_vw_objektbezeichnung') id_st_vw_objektbezeichnung
 from verundentsorgung.aw_lin_haltung limit 10;
*/
vSQL := '
SELECT t.schemaname table_schema,
       t.tablename  table_name
   FROM pg_tables t
  WHERE t.schemaname = $1
   and ( SELECT count(*) FROM information_schema.columns c WHERE c.column_name in (''id'', ''id_st_vw_projekt'', ''name_number'', ''geometry'') and c.table_schema = t.schemaname and c.table_name = t.tablename ) = 4
   and t.tablename not like ''%label'' and t.tablename not like ''%alt'' and t.tablename not like ''%topolo%'' ';
vSQL := 'select id id, table_schema, table_name from '||vtable_schema||'.st_vw_objektbezeichnung where 
table_schema = $1 and table_name not like ''%label'' and table_name not like ''%alt'' and table_name not like ''%topolo%'' 
and table_name not in (''wa_pkt_einbauteil'',''unbekannt'') and id_st_vw_projekt = $2';
for vRC in execute vSQL using vtable_schema , vid_st_vw_projekt loop
vSQL := 'select count(*) from '||vRC.table_schema||'.'||vRC.table_name||' where id = $1 and id_st_vw_projekt = $2'; execute vSQL into vZ using vID, vid_st_vw_projekt;
  if vZ > 0 then 
   if vRUECKGABE = 'table_name' then raise notice '%', vRC.table_schema||'.'||vRC.table_name; vRETURN := vRC.table_name; end if;
   if vRUECKGABE = 'name_number' then vSQL := 'select '||vRUECKGABE||' from '||vRC.table_schema||'.'||vRC.table_name||' where id = $1 and id_st_vw_projekt = $2'; execute vSQL into vRETURN using vID, vid_st_vw_projekt; raise notice '%', vRETURN; end if;
   if vRUECKGABE = 'id_st_vw_objektbezeichnung' then raise notice '%', vRC.id; vRETURN := vRC.id::text; end if; --vSQL := 'select id::text from '||vRC.table_schema||'.st_vw_objektbezeichnung where table_schema = $1 and table_name = $2 and id_st_vw_projekt = $3'; execute vSQL into vRETURN using vRC.table_schema, vRC.table_name, vid_st_vw_projekt; raise notice '%', vRETURN; end if;
  end if;
end loop;
return vRETURN;
end;
$_$;


