			d.id                         as regel_id,
            o.langtext                   AS objekt_tabelle,
			replace(d.attributregel, '$id', quote_literal(l.id_objekt::text)) as Regel
        FROM verundentsorgung.wa_pkt_label l
        JOIN verundentsorgung.st_vw_label_definition d
            ON d.id = l.id_st_vw_label_definition
        JOIN verundentsorgung.st_vw_objektbezeichnung o
            ON o.id = l.id_st_vw_objektbezeichnung
        WHERE l.id_objekt = vid_objekt
    LOOP
raise notice '%',rec.regel_id;

if rec.regel = 'unbekannt' then return 'f'; end if ;

		execute rec.regel into  vLabel_text;
			--raise notice '%',rec.regel;
			--raise notice '%',vLabel_text;
		


		IF vLabel_text IS NULL THEN
    		RETURN 'f';
		END IF;

        
        UPDATE verundentsorgung.wa_pkt_label
        SET labeltext = vLabel_text,
            layout    = vLayout
        WHERE id = rec.label_id;
    END LOOP;

    RETURN 't';
END;
$_$;


--
-- TOC entry 28649 (class 1255 OID 43463363)
-- Name: rgb_to_hex(text); Type: FUNCTION; Schema: verundentsorgung; Owner: -
--

CREATE FUNCTION verundentsorgung.rgb_to_hex(vrgbstring text) RETURNS text
    LANGUAGE plpgsql
    AS $_$
declare
vR integer;
vG integer;
vB integer;
vSQL text;
BEGIN
--select verundentsorgung.rgb_to_hex( '(82,142,214,255)'::text );
--select verundentsorgung.rgb_to_hex( '(8a2,142,214,255)'::text ); --bei Fehler Schwarz '#F0F8FF'
vSQL := 'select r[1] r, r[2] g, r[3] b from ( select string_to_array( replace( replace(r, ''('', ''''), '')'',''''), '','' ) r from ( select $1 r ) r ) r';
execute vSQL into vR, vG, vB using vRGBSTRING;
    RETURN concat('#' , LPAD(TO_HEX(vr::integer), 2, '0') , LPAD(TO_HEX(vg::integer), 2, '0') , LPAD(TO_HEX(vb::integer), 2, '0'));
exception when others then return '#F0F8FF';
end;
$_$;


--
-- TOC entry 28777 (class 1255 OID 59068226)
-- Name: rgb_to_hex_2(text); Type: FUNCTION; Schema: verundentsorgung; Owner: -
--

CREATE FUNCTION verundentsorgung.rgb_to_hex_2(vrgbstring text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
    SELECT
        CASE
            WHEN vrgbstring IS NULL THEN '#F0F8FF'
            ELSE
                '#' ||
                lpad(to_hex((parts[1])::int), 2, '0') ||
                lpad(to_hex((parts[2])::int), 2, '0') ||
                lpad(to_hex((parts[3])::int), 2, '0')
        END
    FROM (
        SELECT string_to_array(
                   replace(replace(vrgbstring, '(', ''), ')', ''),
                   ','
               ) AS parts
    ) s;
$$;


