           execute vSQL into vpid, vdatname, vapplication_name, vclient_addr, vclient_hostname, vclient_port, vbackend_type using pg_backend_pid();
           vsql  := 'INSERT INTO '||vTG_TABLE_SCHEMA||'.'||vTG_TABLE_NAME||'_hist
                     SELECT $1, $2, now(), user, $3, $4, $5, $6, $7, $8, $9, o.* FROM old_table o'; 
           execute vsql using vUUID, vTG_OP, vpid, vdatname, vapplication_name, vclient_addr, vclient_hostname, vclient_port, vbackend_type;
raise notice '%', concat(vPROJEKTPARAMETER_WERT_notiz, ', ', vNOTICE_PRAEFIX);
end if; --if vPROJEKTPARAMETER_WERT_AKTIVSTATUS = 1 and vTG_OP in ( 'UPDATE', 'DELETE' ) then
--
end if; --if 1 = 2 then --wird über Trigger verundentsorgung.tf_standard_after umgesetzt

if vTG_OP in ('INSERT','UPDATE') then RETURN new; else RETURN old; end if;
