--
-- TOC entry 28795 (class 1255 OID 62252655)
-- Name: tf_konstruktion_before(); Type: FUNCTION; Schema: verundentsorgung; Owner: -
--

CREATE FUNCTION verundentsorgung.tf_konstruktion_before() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN

INSERT INTO verundentsorgung.st_konstruktion_lin
(
    id, geometry, id_strassenelement, gueltig_von, gueltig_bis,
    angelegt_am, angelegt_von, geaendert_am, geaendert_von,
    ident_hist, bemerkung, id_st_vw_projekt, name_number,
    leistungsobjekt, id_st_strasse, hausnummer, hausnummerzusatz,
    lagezusatz, herkunftsplan, id_st_vw_betriebsstatus,
    id_st_vw_eigentuemer, id_st_vw_betreiber, id_st_vw_material,
    id_st_vw_lagestatus, baujahr, migrationsdatum
)
SELECT
    NEW.id,
    ST_Boundary(
        ST_Buffer(
            NEW.geometry,
            NEW.radius,
            'quad_segs=16'
        )
    ),
    NEW.id_strassenelement,
    NEW.gueltig_von,
    NEW.gueltig_bis,
    NEW.angelegt_am,
    NEW.angelegt_von,
    NEW.geaendert_am,
    NEW.geaendert_von,
    NEW.ident_hist,
    NEW.bemerkung,
    NEW.id_st_vw_projekt,
    NEW.name_number,
    NEW.leistungsobjekt,
    NEW.id_st_strasse,
    NEW.hausnummer,
    NEW.hausnummerzusatz,
    NEW.lagezusatz,
    NEW.herkunftsplan,
    NEW.id_st_vw_betriebsstatus,
    NEW.id_st_vw_eigentuemer,
    NEW.id_st_vw_betreiber,
    NEW.id_st_vw_material,
    NEW.id_st_vw_lagestatus,
    NEW.baujahr,
    NEW.migrationsdatum
WHERE NEW.kreis_erstellen = true;


NEW.kreis_erstellen := false;

RETURN NEW;

END;
$$;


--
-- TOC entry 28630 (class 1255 OID 39683689)
-- Name: tf_laenge_gefaelle(); Type: FUNCTION; Schema: verundentsorgung; Owner: -
--

CREATE FUNCTION verundentsorgung.tf_laenge_gefaelle() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
declare
vSQL   text;
vZ     integer default 1;
vRC    record;
vCHARS char[];
vPROJEKTPARAMETER_WERT_KURZTEXT         text;
vPROJEKTPARAMETER_WERT_AKTIVSTATUS      numeric;
vPROJEKTPARAMETER_WERT_NUMERIC          numeric;
vPROJEKTPARAMETER_WERT_VARCHAR          text;
vPROJEKTPARAMETER_WERT_TIMESTAMP        timestamp;
vPROJEKTPARAMETER_WERT_id_st_vw_projekt text;
vPROJEKTPARAMETER_WERT_notiz            text DEFAULT 'unbekannt';
vPROJEKTPARAMETER_WERT_fehlermeldung    text DEFAULT 'unbekannt';
vTG_NAME                                text default TG_NAME ;
vTG_TABLE_SCHEMA                        text default TG_TABLE_SCHEMA ;
vTG_TABLE_NAME                          text default TG_TABLE_NAME ;
vTG_OP                                  text default TG_OP ; --INSERT, UPDATE, DELETE, oder TRUNCATE.
vERRORMELDUNG                           text;
vNOTICE_PRAEFIX                         text default concat('TG_NAME: ', TG_NAME, ', TG_TABLE_SCHEMA: ', TG_TABLE_SCHEMA, ', TG_TABLE_NAME: ', TG_TABLE_NAME, ', TG_OP: ', TG_OP);
begin
if 1 = 2 then --wird über Trigger verundentsorgung.tf_standard_before umgesetzt
vPROJEKTPARAMETER_WERT_KURZTEXT := 'laenge';	
vSQL := 'select wert_aktivstatus, wert_numerisch, wert_text, wert_timestamptz, id_st_vw_projekt, notiz, fehlermeldung from '||vTG_TABLE_SCHEMA||'.admin_projekt_parameter where kurztext = $1 and id_st_vw_projekt = $2'; 
execute vSQL into vPROJEKTPARAMETER_WERT_AKTIVSTATUS, vPROJEKTPARAMETER_WERT_NUMERIC, vPROJEKTPARAMETER_WERT_VARCHAR, vPROJEKTPARAMETER_WERT_TIMESTAMP, vPROJEKTPARAMETER_WERT_id_st_vw_projekt, vPROJEKTPARAMETER_WERT_notiz, vPROJEKTPARAMETER_WERT_fehlermeldung using vPROJEKTPARAMETER_WERT_KURZTEXT, new.id_st_vw_projekt;
if vPROJEKTPARAMETER_WERT_AKTIVSTATUS = 1 and vPROJEKTPARAMETER_WERT_id_st_vw_projekt = new.id_st_vw_projekt then
  if round(st_length(new.geometry)::numeric, vPROJEKTPARAMETER_WERT_NUMERIC::integer)::numeric > 0 then
    NEW.laenge := round(st_length(new.geometry)::numeric, vPROJEKTPARAMETER_WERT_NUMERIC::integer)::numeric;
    raise notice '%', concat(vPROJEKTPARAMETER_WERT_notiz, ', ', vNOTICE_PRAEFIX);
  end if;
end if; -- vPROJEKTPARAMETER_WERT_AKTIVSTATUS = 1 and vPROJEKTPARAMETER_WERT_id_st_vw_projekt = new.id_st_vw_projekt then
--
if vTG_TABLE_NAME = 'aw_lin_haltung' then
vPROJEKTPARAMETER_WERT_KURZTEXT := 'gefaelle';
vSQL := 'select wert_aktivstatus, wert_numerisch, wert_text, wert_timestamptz, id_st_vw_projekt, notiz, fehlermeldung from '||vTG_TABLE_SCHEMA||'.admin_projekt_parameter where kurztext = $1 and id_st_vw_projekt = $2'; 
execute vSQL into vPROJEKTPARAMETER_WERT_AKTIVSTATUS, vPROJEKTPARAMETER_WERT_NUMERIC, vPROJEKTPARAMETER_WERT_VARCHAR, vPROJEKTPARAMETER_WERT_TIMESTAMP, vPROJEKTPARAMETER_WERT_id_st_vw_projekt, vPROJEKTPARAMETER_WERT_notiz, vPROJEKTPARAMETER_WERT_fehlermeldung using vPROJEKTPARAMETER_WERT_KURZTEXT, new.id_st_vw_projekt;
if vPROJEKTPARAMETER_WERT_AKTIVSTATUS = 1 and vPROJEKTPARAMETER_WERT_id_st_vw_projekt = new.id_st_vw_projekt then
  if round(st_length(new.geometry)::numeric, vPROJEKTPARAMETER_WERT_NUMERIC::integer)::numeric > 0 then
     --round(st_length(new.geometry)::numeric, vPROJEKTPARAMETER_WERT_NUMERIC::integer)::numeric;
	  if new.einlaufhoehe is not null and new.einlaufhoehe != 0 and new.ablaufhoehe is not null and new.ablaufhoehe != 0 then
	  --case when einlaufhoehe is not null and einlaufhoehe != 0 and ablaufhoehe is not null and ablaufhoehe != 0 then round((ablaufhoehe-einlaufhoehe)/round(st_length(geometry)::numeric,2)*1000, 2) end gefaelle_gerechnet
	    NEW.haltungsgefaelle:= round( (new.ablaufhoehe-new.einlaufhoehe) / round(st_length(new.geometry)::numeric, vPROJEKTPARAMETER_WERT_NUMERIC::integer)::numeric*1000::numeric, vPROJEKTPARAMETER_WERT_NUMERIC::integer); 
	  end if; --new.einlaufhoehe is not null and new.einlaufhoehe != 0 and new.ablaufhoehe is not null and new.ablaufhoehe != 0 
    raise notice '%', concat(vPROJEKTPARAMETER_WERT_notiz, ', ', vNOTICE_PRAEFIX);
  end if;
