    verror_hint   = PG_EXCEPTION_HINT,
    verror_context= PG_EXCEPTION_CONTEXT;
    PERFORM verundentsorgung.f_admin_error_log( verror_state, verror_text, verror_detail, verror_hint, verror_context, TG_NAME, vid_st_vw_projekt );
RAISE;*/
-- 

