--        RAISE NOTICE 'Zeit Funktion After: % Sekunden',  EXTRACT(EPOCH FROM (vFunktionende - vFunktionstart));
--END IF;

if vNOTICE = '1' then raise notice '%', concat('07. ','Ende'); end if;
IF TG_OP IN ('INSERT', 'UPDATE') THEN
    RETURN NEW;
ELSE
    RETURN OLD;
END IF;
raise notice 'end';
END;
