						execute 'INSERT INTO '||TG_TABLE_SCHEMA||'.st_idents (name_number, table_schema, table_name, id_st_vw_projekt) VALUES ($1, $2, $3, $4)' using vNEW_NAME_NUMBER, TG_TABLE_SCHEMA, TG_TABLE_NAME, new.id_st_vw_projekt;
