elseif TG_OP::text in ( 'UPDATE'::text ) and ( position( '_pkt_' in TG_TABLE_NAME ) > 0 or position( '_lin_' in TG_TABLE_NAME ) > 0 or position( '_fla_' in TG_TABLE_NAME ) > 0 ) and TG_TABLE_NAME not in ('aw_lin_topologie', 'aw_pkt_topologie','aw_pkt_richtungspfeil') and vZ::int > 0::int and vPROJEKTPARAMETER_WERT_AKTIVSTATUS::int = 1::int and vPROJEKTPARAMETER_WERT_id_st_vw_projekt = old.id_st_vw_projekt and TG_TABLE_NAME::text not in ('st_idents'::text) and TG_TABLE_NAME::text not like ('%_hist') then
if vNOTIZEN = 1 then raise notice '%', concat('Tracepoint '||vPROJEKTPARAMETER_WERT_SORTIERREIHENFOLGE||' Begin Update  '||vPROJEKTPARAMETER_WERT_KURZTEXT||', TG_TABLE_NAME: ', TG_TABLE_NAME, ', TG_NAME: ', TG_NAME, ' vUUID: ', vUUID::text ); end if;
  NEW.name_number := vNEW_NAME_NUMBER;
if vNOTIZEN = 1 then raise notice '%', concat('Tracepoint '||vPROJEKTPARAMETER_WERT_SORTIERREIHENFOLGE||' Ende  Update  '||vPROJEKTPARAMETER_WERT_KURZTEXT||', TG_TABLE_NAME: ', TG_TABLE_NAME, ', TG_NAME: ', TG_NAME, ' vUUID: ', vUUID::text, ', name_number: ', NEW.name_number ); end if;
elseif TG_OP::text in ( 'DELETE'::text ) and ( position( '_pkt_' in TG_TABLE_NAME ) > 0 or position( '_lin_' in TG_TABLE_NAME ) > 0 or position( '_fla_' in TG_TABLE_NAME ) > 0 ) and TG_TABLE_NAME not in ('aw_lin_topologie', 'aw_pkt_topologie','aw_pkt_richtungspfeil') and vZ::int > 0::int and vPROJEKTPARAMETER_WERT_AKTIVSTATUS::int = 1::int and vPROJEKTPARAMETER_WERT_id_st_vw_projekt = old.id_st_vw_projekt and TG_TABLE_NAME::text not in ('st_idents'::text) and TG_TABLE_NAME::text not like ('%_hist') then
if vNOTIZEN = 1 then raise notice '%', concat('Tracepoint '||vPROJEKTPARAMETER_WERT_SORTIERREIHENFOLGE||' Beginn delete '||vPROJEKTPARAMETER_WERT_KURZTEXT||', TG_TABLE_NAME: ', TG_TABLE_NAME, ', TG_NAME: ', TG_NAME, ' vUUID: ', vUUID::text ); end if;
      execute 'DELETE FROM '||TG_TABLE_SCHEMA||'.st_idents WHERE name_number = $1 and table_schema = $2 and table_name = $3 and id_st_vw_projekt = $4' using vNAME_NUMBER, TG_TABLE_SCHEMA, TG_TABLE_NAME, OLD.id_st_vw_projekt;
if vNOTIZEN = 1 then raise notice '%', concat('Tracepoint '||vPROJEKTPARAMETER_WERT_SORTIERREIHENFOLGE||' Ende   delete '||vPROJEKTPARAMETER_WERT_KURZTEXT||', TG_TABLE_NAME: ', TG_TABLE_NAME, ', TG_NAME: ', TG_NAME, ' vUUID: ', vUUID::text, ', name_number: ', old.name_number ); end if;
end if;
end if; --if TG_TABLE_NAME not like 'st_%' then
