	         vGEFAELLE := round( (new.ablaufhoehe-new.einlaufhoehe) / round(st_length(new.geometry)::numeric, vPROJEKTPARAMETER_WERT_NUMERIC::integer)::numeric*1000::numeric, vPROJEKTPARAMETER_WERT_NUMERIC::integer); 
