                       --, '||TG_TABLE_SCHEMA||'.st_vw_medium hlm
                       --, '||TG_TABLE_SCHEMA||'.st_vw_medium alm
                   where 
 				   hl.id_st_vw_projekt      = $2
                   and hl.id_st_vw_projekt  = al.id_st_vw_projekt::uuid
                   and hl.id_st_vw_medium   = med.id
                   AND ST_DWithin(ST_StartPoint(al.geometry), hl.geometry, 0.5)
                   --
			       /*AND NOT ST_DWithin(ST_EndPoint(al.geometry), ST_StartPoint(hl.geometry), 0.5)
			       AND NOT ST_DWithin(ST_EndPoint(al.geometry), ST_EndPoint(hl.geometry), 0.5)
			       AND NOT ST_DWithin(ST_StartPoint(al.geometry), ST_StartPoint(hl.geometry), 0.5)
