  vPROJEKTPARAMETER_WERT_KURZTEXT := 'verbindung_ABO_Winkel';
  if TG_OP in ( 'INSERT' ) and TG_TABLE_NAME = 'aw_pkt_verbindungen' then 
--if vLaufzeit = 1 then	SELECT clock_timestamp() INTO vStartzeit; end if;	
  	  execute vSQLAKTIVSTATUSABFRAGE into vPROJEKTPARAMETER_WERT_AKTIVSTATUS, vPROJEKTPARAMETER_WERT_NUMERIC, vPROJEKTPARAMETER_WERT_text, vPROJEKTPARAMETER_WERT_TIMESTAMP, vPROJEKTPARAMETER_WERT_id_st_vw_projekt, vPROJEKTPARAMETER_WERT_notiz, vPROJEKTPARAMETER_WERT_fehlermeldung, vPROJEKTPARAMETER_WERT_SORTIERREIHENFOLGE, vPROJEKTPARAMETER_WERT_BEMERKUNG using vPROJEKTPARAMETER_WERT_KURZTEXT, new.id_st_vw_projekt;
      if vPROJEKTPARAMETER_WERT_AKTIVSTATUS > 0 then 

		vSQL:= 'select ''1'' from verundentsorgung.st_vw_verbindungstyp where id = $1 
			and kurztext IN (''ABOLRS'',''ABOL'',''ABOL1'',''ABOL1S'',''ABOL1SD'',''ABOL1U'',''ABOL1D'',''ABORZ'',''ABOR'',''ABOR1'',''ABOR1S'',''ABOR1SD'',''ABOR1U'',''ABOR1D'',''ABOLRS'')';
		execute vSQL into vdummy using new.id_st_vw_verbindungstyp;

		if vdummy::numeric = 1 then

			vSQL := 'select  geometry 
			from verundentsorgung.aw_lin_haltung 
			where st_dwithin(geometry, $1,0.05 )
				and not st_dwithin(st_startpoint(geometry), $1,0.02 )
				and not st_dwithin(st_endpoint(geometry), $1,0.02 )
				limit 1;';
			execute vSQL into vhaltung_geom using new.geometry;
	
	
		    vpunkt_haltung := ST_LineLocatePoint(vhaltung_geom, new.geometry);
		
		    vpunkt_haltung_vor := ST_LineInterpolatePoint(vhaltung_geom, GREATEST(vpunkt_haltung - 0.00001, 0));
		    vpunkt_haltung_hinter  := ST_LineInterpolatePoint(vhaltung_geom, LEAST(vpunkt_haltung + 0.00001, 1));
		
		    -- Compute the azimuth (radians → degrees)
		    vwinkel := degrees(ST_Azimuth(vpunkt_haltung_vor, vpunkt_haltung_hinter)) -90;
	
			new.orientation = vwinkel;
			--end if;
         end if;
      end if; --if vPROJEKTPARAMETER_WERT_AKTIVSTATUS > 0 then
  end if;



