--
verror_state          text;
verror_text           text;
verror_detail         text;
verror_hint           text;
verror_context        text;   
vid_st_vw_projekt     text;
begin
   if TG_OP in ('INSERT', 'UPDATE') then
     vid_st_vw_projekt := new.id_st_vw_projekt; 
   elseif TG_OP in ('DELETE', 'TRUNCATE') then 
     vid_st_vw_projekt := old.id_st_vw_projekt; 
   end if;
if 1 = 1 then raise notice '%', 'Test'; end if;
/*
