--
-- TOC entry 28723 (class 1255 OID 55144825)
-- Name: tmp_haltungswinkel_am_punkt(public.geometry, public.geometry); Type: FUNCTION; Schema: verundentsorgung; Owner: -
--

CREATE FUNCTION verundentsorgung.tmp_haltungswinkel_am_punkt(haltung public.geometry, punkt public.geometry) RETURNS double precision
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
    punkt_haltung double precision;
    winkel double precision;
    punkt_haltung_vor geometry;
    punkt_haltung_hinter geometry;
BEGIN
    
    punkt_haltung := ST_LineLocatePoint(Haltung, punkt);

    punkt_haltung_vor := ST_LineInterpolatePoint(haltung, GREATEST(punkt_haltung - 0.00001, 0));
    punkt_haltung_hinter  := ST_LineInterpolatePoint(haltung, LEAST(punkt_haltung + 0.00001, 1));

    -- Compute the azimuth (radians → degrees)
    winkel := degrees(ST_Azimuth(punkt_haltung_vor, punkt_haltung_hinter)) -90;

    RETURN winkel;
END;
$$;


--
-- TOC entry 28793 (class 1255 OID 61816041)
-- Name: x_y_to_excel_hyperlink(text, text, text, text); Type: FUNCTION; Schema: verundentsorgung; Owner: -
--

CREATE FUNCTION verundentsorgung.x_y_to_excel_hyperlink(vx text, vy text, vquellepsg text, vhyperlinkalias text) RETURNS text
    LANGUAGE plpgsql
    AS $$
declare
vXNeu text default '0';
vYNeu text default '0';
vRETURN text default '0';
vSQL text;
vZIELEPSG text default '4326';
BEGIN
if length(vX) > 7 and length(vY) > 7 then
vSQL := 'SELECT st_Y(ST_Transform(ST_GeomFromText(''POINT('||vX::text||' '||vY::text||')'', '||vQUELLEPSG||'), '||vZIELEPSG||'))::text googleaufruf';
raise notice '%', vSQL;
execute vSQL into vYNeu using vQUELLEPSG::numeric, vZIELEPSG::numeric;
vSQL := 'SELECT st_X(ST_Transform(ST_GeomFromText(''POINT('||vX::text||' '||vY::text||')'', '||vQUELLEPSG||'), '||vZIELEPSG||'))::text googleaufruf';
raise notice '%', vSQL;
execute vSQL into vXNeu using vQUELLEPSG::numeric, vZIELEPSG::numeric;
end if;
--return concat(vY, ' ', vX);
vRETURN := '=HYPERLINK("https://www.google.com/maps/search/?api=1&query=" &"'||vYNeu||' '||vXNeu||'";"GoogleLink: '||vHYPERLINKALIAS||'")';
raise notice '%', vRETURN;
return vRETURN;
END;
$$;


