-- TOC entry 12291 (class 1259 OID 39684130)
-- Name: aw_pkt_klaertank; Type: TABLE; Schema: verundentsorgung; Owner: -
--

CREATE TABLE verundentsorgung.aw_pkt_klaertank (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    fid_hist text DEFAULT 'unbekannt'::text NOT NULL,
    name_number text DEFAULT 'unbekannt'::text NOT NULL,
    gueltig_von timestamp with time zone DEFAULT now() NOT NULL,
    gueltig_bis timestamp with time zone DEFAULT '2100-01-01 00:00:00+01'::timestamp with time zone NOT NULL,
    angelegt_am timestamp with time zone DEFAULT now() NOT NULL,
    angelegt_von text DEFAULT 'unbekannt'::text NOT NULL,
    geaendert_am timestamp with time zone DEFAULT now() NOT NULL,
    geaendert_von text DEFAULT 'unbekannt'::text NOT NULL,
    leistungsobjekt text,
    bemerkung text,
    id_st_strasse uuid DEFAULT '00000000-0000-0000-0000-000000000000'::uuid NOT NULL,
    hausnummer text,
    hausnummerzusatz text,
    lagezusatz text,
    herkunftsplan text,
    id_st_vw_projekt uuid DEFAULT '00000000-0000-0000-0000-000000000000'::uuid NOT NULL,
    id_st_vw_betriebsstatus uuid DEFAULT '00000000-0000-0000-0000-000000000000'::uuid NOT NULL,
    id_st_vw_eigentuemer uuid DEFAULT '00000000-0000-0000-0000-000000000000'::uuid NOT NULL,
    id_st_vw_betreiber uuid DEFAULT '00000000-0000-0000-0000-000000000000'::uuid NOT NULL,
    id_st_vw_material uuid DEFAULT '00000000-0000-0000-0000-000000000000'::uuid NOT NULL,
    id_st_vw_medium uuid DEFAULT '00000000-0000-0000-0000-000000000000'::uuid NOT NULL,
    id_st_vw_lagestatus uuid DEFAULT '00000000-0000-0000-0000-000000000000'::uuid NOT NULL,
    geometry public.geometry(Point,25833) NOT NULL,
    baujahr integer,
    migrationsdatum timestamp with time zone DEFAULT now() NOT NULL,
    sohlhoehe numeric(10,2),
    drehung numeric(10,2),
    id_suche text,
    id_st_vw_tankverwendung uuid DEFAULT '00000000-0000-0000-0000-000000000000'::uuid NOT NULL,
    okg numeric(10,2),
    dimension_1 text,
    dimension_2 text,
    area text,
    capacity text,
    flow_rate text,
    soil_percolation_rate text,
    id_st_vw_struckturbedingung uuid DEFAULT '00000000-0000-0000-0000-000000000000'::uuid NOT NULL,
    installateur text,
    orientation numeric(10,2),
    layout jsonb,
    tiefbau_durch text,
    vermessung_durch text,
    CONSTRAINT ck_aw_pkt_klaertank_baujahr CHECK (((baujahr >= 1800) AND (baujahr <= 2050)))
);


