    id_st_vw_medium uuid DEFAULT '00000000-0000-0000-0000-000000000000'::uuid NOT NULL,
    id_st_vw_lagestatus uuid DEFAULT '00000000-0000-0000-0000-000000000000'::uuid NOT NULL,
    geometry public.geometry(Point,25833) NOT NULL,
    baujahr integer,
    migrationsdatum timestamp with time zone DEFAULT now() NOT NULL,
    wandstaerke text,
    innendurchmesser numeric(10,0),
    aussendurchmesser numeric(10,0),
    layout jsonb,
    okr numeric,
    okg numeric,
    sohlhoehe numeric,
    drehung numeric,
    orientation numeric,
    zvg_leo character varying,
    gemeinde_schluessel character varying,
    id_st_vw_verbindungstyp uuid DEFAULT '00000000-0000-0000-0000-000000000000'::uuid NOT NULL,
    id_objekt uuid,
    tiefbau_durch text,
    vermessung_durch text,
    CONSTRAINT ck_aw_pkt_schutzrohr_baujahr CHECK (((baujahr >= 1800) AND (baujahr <= 2050)))
);


