--
-- TOC entry 21115 (class 1259 OID 46618806)
-- Name: aw_pkt_schachtdeckel_v; Type: VIEW; Schema: verundentsorgung; Owner: -
--

CREATE VIEW verundentsorgung.aw_pkt_schachtdeckel_v AS
 SELECT b.id,
    b.fid_hist,
    b.name_number,
    "left"((b.gueltig_von)::text, 16) AS gueltig_von,
    "left"((b.gueltig_bis)::text, 16) AS gueltig_bis,
    "left"((b.angelegt_am)::text, 10) AS angelegt_am,
    b.angelegt_von,
    "left"((b.geaendert_am)::text, 10) AS geaendert_am,
    b.geaendert_von,
    b.leistungsobjekt,
    b.bemerkung,
    b.id_st_strasse,
    b.hausnummer,
    b.hausnummerzusatz,
    b.lagezusatz,
    b.herkunftsplan,
    b.id_st_vw_projekt,
    b.id_st_vw_betriebsstatus,
    b.id_st_vw_eigentuemer,
    b.id_st_vw_betreiber,
    b.id_st_vw_material,
    b.id_st_vw_medium,
    b.id_st_vw_lagestatus,
    b.id_st_vw_schachtdeckeltyp,
    b.id_st_vw_lastklassen,
    b.id_st_vw_abdeckungsform,
    b.id_st_vw_belueftung,
    b.id_st_vw_deckel_herst_typ AS id_st_vw_zvg_deckel_herst_typ,
    b.geometry,
    s.amt,
    s.gemeinde,
    s.ort,
    s.strasse,
    p.kurztext AS projekt_kurztext,
    p.langtext AS projekt_langtext,
    bs.kurztext AS betriebsstatus_kurztext,
    bs.langtext AS betriebsstatus_langtext,
    eig.kurztext AS eigentuemer_kurztext,
    eig.langtext AS eigentuemer_langtext,
    betr.kurztext AS betreiber_kurztext,
    betr.langtext AS betreiber_langtext,
    mat.kurztext AS material_kurztext,
    mat.langtext AS material_langtext,
    med.kurztext AS medium_kurztext,
    med.langtext AS medium_langtext,
    ls.kurztext AS lagestatus_kurztext,
    ls.langtext AS lagestatus_langtext,
    st.kurztext AS schachtdeckeltyp_kurztext,
    st.langtext AS schachtdeckeltyp_langtext,
    lk.kurztext AS lastklasse_kurztext,
    lk.langtext AS lastklasse_langtext,
    af.kurztext AS abdeckungsform_kurztext,
    af.langtext AS abdeckungsform_langtext,
    bl.kurztext AS belueftung_kurztext,
    bl.langtext AS belueftung_langtext,
    dh.kurztext AS zvg_deckel_herst_typ_kurztext,
    dh.langtext AS zvg_deckel_herst_typ_langtext,
    (b.baujahr)::text AS baujahr,
    concat(b.name_number, ' ', 'AW-Schachtdeckel') AS id_suche,
    b.dn_laenge,
    b.breite,
    b.zvg_leo,
    b.leo_pruefung,
    b.sanierung_datum,
    b.deckelhoehe,
    b.lagegenauigkeit,
    b.hoehengenauigkeit,
    b.plannr,
    b.tabellen_beschreibung,
    b.anz_dokumente,
    b.layout
   FROM (((((((((((((verundentsorgung.aw_pkt_schachtdeckel b
     LEFT JOIN verundentsorgung.strassenschluessel_v s ON ((b.id_st_strasse = s.id)))
     LEFT JOIN verundentsorgung.st_vw_projekt p ON ((b.id_st_vw_projekt = p.id)))
     LEFT JOIN verundentsorgung.st_vw_betriebsstatus bs ON ((b.id_st_vw_betriebsstatus = bs.id)))
     LEFT JOIN verundentsorgung.st_vw_eigentuemer eig ON ((b.id_st_vw_eigentuemer = eig.id)))
     LEFT JOIN verundentsorgung.st_vw_betreiber betr ON ((b.id_st_vw_betreiber = betr.id)))
     LEFT JOIN verundentsorgung.st_vw_material mat ON ((b.id_st_vw_material = mat.id)))
     LEFT JOIN verundentsorgung.st_vw_medium med ON ((b.id_st_vw_medium = med.id)))
     LEFT JOIN verundentsorgung.st_vw_lagestatus ls ON ((b.id_st_vw_lagestatus = ls.id)))
     LEFT JOIN verundentsorgung.st_vw_schachtdeckeltyp st ON ((b.id_st_vw_schachtdeckeltyp = st.id)))
     LEFT JOIN verundentsorgung.st_vw_lastklassen lk ON ((b.id_st_vw_lastklassen = lk.id)))
     LEFT JOIN verundentsorgung.st_vw_abdeckungsform af ON ((b.id_st_vw_abdeckungsform = af.id)))
     LEFT JOIN verundentsorgung.st_vw_belueftung bl ON ((b.id_st_vw_belueftung = bl.id)))
     LEFT JOIN verundentsorgung.st_vw_deckel_herst_typ dh ON ((b.id_st_vw_deckel_herst_typ = dh.id)))
  WHERE (b.gueltig_bis > now());


