CREATE VIEW verundentsorgung.admin_benutzer2admin_benutzergruppe2objekt_v AS
 SELECT t.quelle,
    t.schema_name,
    t.objektname,
    bg.benutzergruppe,
    bg.tabellenpraefix,
    COALESCE(
        CASE
            WHEN (t.quelle = 'view'::text) THEN 'select'::text
            ELSE
            CASE
                WHEN (t.quelle = 'function'::text) THEN 'execute'::text
                ELSE
                CASE
                    WHEN (bg.benutzergruppe = 'verundentsorgung_viewer_zvg_gruppe'::text) THEN 'select'::text
                    ELSE
                    CASE
                        WHEN (bg.benutzergruppe = 'verundentsorgung_erfasser_zvg_gruppe'::text) THEN 'select, insert, update, delete'::text
                        ELSE
                        CASE
                            WHEN (bg.tabellenpraefix = "substring"(t.objektname, 1, 2)) THEN bg.datenbankrecht
                            ELSE NULL::text
                        END
                    END
                END
            END
        END, 'select'::text) AS datenbankrecht
   FROM ( SELECT 'view'::text AS quelle,
            (views.table_schema)::text AS schema_name,
            (views.table_name)::text AS objektname
           FROM information_schema.views
          WHERE (((views.table_schema)::name = 'verundentsorgung'::name) AND (NOT (((views.table_schema)::text, (views.table_name)::text) IN ( SELECT (views_1.table_schema)::text AS table_schema,
                    (views_1.table_name)::text AS table_name
                   FROM information_schema.views views_1))) AND (("substring"((views.table_name)::text, 1, 3) = ANY (ARRAY['al_'::text, 'aw_'::text, 'ka_'::text, 'so_'::text, 'st_'::text, 'ta_'::text, 'wa_'::text])) OR ((views.table_name)::name = 'strassenschluessel_v'::name)))
        UNION
         SELECT 'table'::text AS quelle,
            (tables.table_schema)::text AS schema_name,
            (tables.table_name)::text AS objektname
           FROM information_schema.tables
          WHERE (((tables.table_schema)::name = 'verundentsorgung'::name) AND (NOT (((tables.table_schema)::text, (tables.table_name)::text) IN ( SELECT (views.table_schema)::text AS table_schema,
                    (views.table_name)::text AS table_name
                   FROM information_schema.views))) AND (("substring"((tables.table_name)::text, 1, 3) = ANY (ARRAY['al_'::text, 'aw_'::text, 'ka_'::text, 'so_'::text, 'st_'::text, 'ta_'::text, 'wa_'::text])) OR ((tables.table_name)::name = ANY (ARRAY['dokument'::name, 'dokument_objekt'::name]))))
        UNION
         SELECT 'function'::text AS quelle,
            (pg_namespace.nspname)::text AS schema_name,
            (pg_proc.proname)::text AS objektname
           FROM (pg_namespace
             JOIN pg_proc ON ((pg_proc.pronamespace = pg_namespace.oid)))
          WHERE ((pg_namespace.nspname = 'verundentsorgung'::name) AND (pg_proc.proname !~~ 'migration%'::text) AND (pg_proc.proname !~~ 'admin%'::text))) t,
    ( SELECT DISTINCT admin_benutzer2admin_benutzergruppe_v.benutzergruppe,
            admin_benutzer2admin_benutzergruppe_v.tabellenpraefix,
            admin_benutzer2admin_benutzergruppe_v.datenbankrecht
           FROM verundentsorgung.admin_benutzer2admin_benutzergruppe_v) bg
  ORDER BY t.schema_name, t.objektname, t.quelle;


