            admin_column_dictionary.numeric_scale,
            admin_column_dictionary.datetime_precision,
            admin_column_dictionary.interval_type,
            admin_column_dictionary.interval_precision,
            admin_column_dictionary.character_set_catalog,
            admin_column_dictionary.character_set_schema,
            admin_column_dictionary.character_set_name,
            admin_column_dictionary.collation_catalog,
            admin_column_dictionary.collation_schema,
            admin_column_dictionary.collation_name,
            admin_column_dictionary.domain_catalog,
