    id_st_vw_lagestatus uuid DEFAULT '00000000-0000-0000-0000-000000000000'::uuid NOT NULL,
    id_st_vw_topologie uuid DEFAULT '00000000-0000-0000-0000-000000000000'::uuid NOT NULL,
    baujahr integer,
    migrationsdatum timestamp with time zone DEFAULT now() NOT NULL,
    orientation numeric(10,2),
    zvg_leo character varying,
    geometry public.geometry(Point,25833) NOT NULL,
    uebernahme text,
    layout jsonb,
    CONSTRAINT ck_ta_pkt_topologie_default_baujahr CHECK (((baujahr >= 1800) AND (baujahr <= 2050)))
);


