--
-- TOC entry 22663 (class 1259 OID 61579560)
-- Name: admin_datensatz_anzahl; Type: VIEW; Schema: verundentsorgung; Owner: -
--

CREATE VIEW verundentsorgung.admin_datensatz_anzahl AS
 SELECT a.a,
    a.id_st_vw_projekt,
    a.table_schema,
    a.table_name
   FROM ( SELECT count(*) AS a,
            (admin_benutzer.id_st_vw_projekt)::text AS id_st_vw_projekt,
            'verundentsorgung'::text AS table_schema,
            'admin_benutzer'::text AS table_name
           FROM verundentsorgung.admin_benutzer
          GROUP BY (admin_benutzer.id_st_vw_projekt)::text
