--
-- TOC entry 22609 (class 1259 OID 61076313)
-- Name: al_fla_koordinatenraster_v; Type: VIEW; Schema: verundentsorgung; Owner: -
--

CREATE VIEW verundentsorgung.al_fla_koordinatenraster_v AS
 SELECT (r.id)::text AS id,
    concat(r.zahl, r.buchstabe) AS id_suche,
    concat(r.zahl, r.buchstabe) AS name_number,
    (r.id_st_vw_projekt)::text AS id_st_vw_projekt,
    p.kurztext AS projekt_kurztext,
    p.langtext AS projekt_langtext,
    "left"((r.gueltig_von)::text, 16) AS gueltig_von,
    "left"((r.gueltig_bis)::text, 16) AS gueltig_bis,
    "left"((r.angelegt_am)::text, 10) AS angelegt_am,
    r.angelegt_von,
    "left"((r.geaendert_am)::text, 10) AS geaendert_am,
    r.geaendert_von,
    r.bemerkung,
    '00000000-0000-0000-0000-000000000000'::text AS id_st_strasse,
    'unbekannt'::text AS amt,
    'unbekannt'::text AS gemeinde,
    'unbekannt'::text AS ort,
    'unbekannt'::text AS strasse,
    'unbekannt'::text AS gemeinde_schluessel,
    r.geometry
   FROM verundentsorgung.al_fla_koordinatenraster r,
    verundentsorgung.st_vw_projekt p
  WHERE (r.id_st_vw_projekt = p.id);


