-- TOC entry 21855 (class 1259 OID 56065226)
-- Name: aw_lin_topologie_v; Type: VIEW; Schema: verundentsorgung; Owner: -
--

CREATE VIEW verundentsorgung.aw_lin_topologie_v AS
 SELECT o.id,
    o.fid_hist,
    o.name_number,
    o.gueltig_von,
    o.gueltig_bis,
    o.angelegt_am,
    o.angelegt_von,
    o.geaendert_am,
    o.geaendert_von,
    o.leistungsobjekt,
    o.bemerkung,
    o.id_st_strasse,
    o.hausnummer,
    o.hausnummerzusatz,
    o.lagezusatz,
    o.herkunftsplan,
    o.id_st_vw_projekt,
    o.id_st_vw_betriebsstatus,
    o.id_st_vw_eigentuemer,
    o.id_st_vw_betreiber,
    o.id_st_vw_material,
    o.id_st_vw_medium,
    o.id_st_vw_lagestatus,
    o.geometry,
    o.id_knoten_oben,
    o.id_knoten_unten,
    o.baujahr,
    o.migrationsdatum,
    o.nennweite,
    o.aussendurchmesser,
    o.sohle_einlaufschacht,
    o.fallhoehe_einlaufschacht,
    o.einlaufnummer,
    o.ablaufhoehe,
    o.auslaufnummer,
    o.einlaufhoehe,
    o.sohle_ablaufschacht,
    o.haltungsgefaelle,
    o.wandstaerke,
    o.plannummer,
    o.knoten_oben,
    o.knoten_unten,
    o.laenge,
    o.id_st_vw_verlegetyp,
    o.id_st_vw_einlaufnummer,
    o.farbwert,
    'aw_lin_haltung'::text AS table_name,
    o.layout,
    concat(o.name_number, ' ', 'AW-LIN-Topologie') AS id_suche
   FROM verundentsorgung.aw_lin_haltung o;


