-- Name: st_vw_linienmarkierungen; Type: TABLE; Schema: verundentsorgung; Owner: -
--

CREATE TABLE verundentsorgung.st_vw_linienmarkierungen (
    id uuid DEFAULT public.uuid_generate_v4() NOT NULL,
    betriebsstatus text[],
    medium text[],
    eigentuemer text[],
    min_length double precision,
    spacing double precision,
    symbol text,
    grose text,
    schrichbreite text,
    fullfarbe text,
    symbol2 text,
    grose2 text,
    schrichbreite2 text,
    fullfarbe2 text,
    versatz_x2 text,
    id_st_vw_projekt uuid DEFAULT '00000000-0000-0000-0000-000000000000'::uuid NOT NULL,
    abstand_start numeric DEFAULT 1 NOT NULL,
    abstand_ende numeric DEFAULT 1 NOT NULL
);


--
-- TOC entry 23219 (class 1259 OID 62799184)
-- Name: aw_pkt_haltungsmakierungen_v; Type: VIEW; Schema: verundentsorgung; Owner: -
--

CREATE VIEW verundentsorgung.aw_pkt_haltungsmakierungen_v AS
 WITH rule_expanded AS (
         SELECT r_1.id,
            r_1.betriebsstatus,
            r_1.medium,
            r_1.eigentuemer,
            r_1.min_length,
            r_1.spacing,
            r_1.symbol,
            r_1.grose,
            r_1.schrichbreite,
            r_1.fullfarbe,
            r_1.symbol2,
            r_1.grose2,
            r_1.schrichbreite2,
            r_1.fullfarbe2,
            r_1.versatz_x2,
            r_1.id_st_vw_projekt,
            r_1.abstand_start,
            r_1.abstand_ende,
            m.id AS medium_id,
            bs.id AS status_id
           FROM ((verundentsorgung.st_vw_linienmarkierungen r_1
             JOIN verundentsorgung.st_vw_medium m ON ((m.kurztext = ANY (r_1.medium))))
             JOIN verundentsorgung.st_vw_betriebsstatus bs ON ((bs.kurztext = ANY (r_1.betriebsstatus))))
        ), base AS (
         SELECT a.geometry,
            a.layout,
            a.id_st_vw_medium,
            a.id_st_vw_betriebsstatus,
            public.st_length(a.geometry) AS len
           FROM verundentsorgung.aw_lin_haltung a
        )
 SELECT r.symbol,
    r.grose,
    r.schrichbreite,
    r.fullfarbe,
    r.symbol2,
    r.grose2,
    r.schrichbreite2,
    r.fullfarbe2,
    r.versatz_x2,
    b.layout,
    public.st_lineinterpolatepoint(b.geometry, d.f) AS geometry,
    (degrees(public.st_azimuth(public.st_lineinterpolatepoint(b.geometry, GREATEST((d.f - (0.0001)::double precision), (0)::double precision)), public.st_lineinterpolatepoint(b.geometry, LEAST((d.f + (0.0001)::double precision), (1)::double precision)))) - (90)::double precision) AS angle,
    row_number() OVER () AS id
   FROM ((base b
     JOIN rule_expanded r ON (((b.id_st_vw_medium = r.medium_id) AND (b.id_st_vw_betriebsstatus = r.status_id))))
     CROSS JOIN LATERAL ( SELECT ((dist.dist)::double precision / b.len) AS f
           FROM generate_series(r.abstand_start, ((b.len)::numeric - r.abstand_ende), (r.spacing)::numeric) dist(dist)) d)
  WHERE (b.len > r.min_length);


