--
-- TOC entry 22469 (class 1259 OID 59066588)
-- Name: aw_pkt_richtungspfeil_v; Type: VIEW; Schema: verundentsorgung; Owner: -
--

CREATE VIEW verundentsorgung.aw_pkt_richtungspfeil_v AS
 SELECT p.id,
    p.fid_hist,
    p.id_aw_pkt_topologie,
    p.id_aw_lin_haltung,
    p.id_st_vw_projekt,
    p.projekt_kurztext,
    p.projekt_langtext,
    p.gueltig_von,
    p.gueltig_bis,
    p.angelegt_am,
    p.angelegt_von,
    p.geaendert_am,
    p.geaendert_von,
    p.bemerkung,
    p.richtungswinkel,
    p.geometry,
    p.layout,
    p.name_number,
    p.id_st_vw_betriebsstatus,
    p.betriebsstatus_kurztext,
    p.betriebsstatus_langtext,
    p.id_st_vw_eigentuemer,
    p.eigentuemer_kurztext,
    p.eigentuemer_langtext,
    p.id_st_vw_betreiber,
    p.betreiber_kurztext,
    p.betreiber_langtext,
    p.id_st_vw_material,
    p.material_kurztext,
    p.material_langtext,
    p.id_st_vw_medium,
    p.medium_kurztext,
    p.medium_langtext,
    p.id_st_vw_lagestatus,
    p.lagestatus_kurztext,
    p.lagestatus_langtext,
    p.id_st_vw_verlegetyp,
    p.verlegetyp_kurztext,
    p.verlegetyp_langtext,
    p.id_st_strasse,
    p.amt,
    p.gemeinde,
    p.ort,
    p.strasse,
    p.hausnummer,
    p.hausnummerzusatz,
    p.leistungsobjekt,
    p.nennweite,
    p.einlaufhoehe,
    p.ablaufhoehe,
    p.baujahr,
    p.id_knoten_oben,
    p.id_knoten_unten,
    p.laenge,
    p.twsz,
    p.kanio_id,
    p.kanio_entw,
    p.id_suche
   FROM ( SELECT p_1.id,
            l.fid_hist,
            p_1.id_aw_pkt_topologie,
            p_1.id_aw_lin_haltung,
            p_1.id_st_vw_projekt,
            l.projekt_kurztext,
            l.projekt_langtext,
            p_1.gueltig_von,
            p_1.gueltig_bis,
            p_1.angelegt_am,
            p_1.angelegt_von,
            p_1.geaendert_am,
            p_1.geaendert_von,
            p_1.bemerkung,
            p_1.richtungswinkel,
            p_1.geometry,
            (replace(replace((l.layout)::text, '"pkt_symbolname": ""'::text, concat('"pkt_symbolname": "',
                CASE
                    WHEN (l.medium_kurztext = ANY (ARRAY['ADL_GAL'::text, 'ADL'::text, 'VS_TRL'::text, 'VS_GAL'::text])) THEN 'RIPFEIDR'::text
                    WHEN (l.medium_kurztext = ANY (ARRAY['KM_TRL'::text, 'KM_GAL'::text])) THEN 'RIPFEIMW'::text
                    WHEN (l.medium_kurztext = ANY (ARRAY['KS_TRL'::text, 'KS_GAL'::text])) THEN 'RIPFEISW'::text
                    WHEN (l.medium_kurztext = ANY (ARRAY['KR_TRL'::text, 'KR_SEL_MU'::text, 'KR_SOL'::text, 'KR_GAL'::text, 'KR_SIL'::text, 'KR_SEL_RI'::text, 'KR_TEIL'::text, 'KR_GRL'::text, 'KR_SIGL'::text, 'KR_SEL'::text, 'RDL_GAL'::text, 'KR_DRGL'::text, 'KR_DRL'::text])) THEN 'RIPFEIRW'::text
                    WHEN (l.medium_kurztext = ANY (ARRAY['GW'::text, 'GW_NUP'::text])) THEN 'RIPFEIRW'::text
                    ELSE NULL::text
                END, '"')), '"pkt_stroke_with": "XXX"'::text, '"pkt_stroke_with": 10'::text))::jsonb AS layout,
            p_1.name_number,
            l.id_st_vw_betriebsstatus,
            l.betriebsstatus_kurztext,
            l.betriebsstatus_langtext,
            l.id_st_vw_eigentuemer,
            l.eigentuemer_kurztext,
            l.eigentuemer_langtext,
            l.id_st_vw_betreiber,
            l.betreiber_kurztext,
            l.betreiber_langtext,
            l.id_st_vw_material,
            l.material_kurztext,
            l.material_langtext,
            l.id_st_vw_medium,
            l.medium_kurztext,
            l.medium_langtext,
            l.id_st_vw_lagestatus,
            l.lagestatus_kurztext,
            l.lagestatus_langtext,
            l.id_st_vw_verlegetyp,
            l.verlegetyp_kurztext,
            l.verlegetyp_langtext,
            l.id_st_strasse,
            l.amt,
            l.gemeinde,
            l.ort,
            l.strasse,
            l.hausnummer,
            l.hausnummerzusatz,
            l.leistungsobjekt,
            l.nennweite,
            l.einlaufhoehe,
            l.ablaufhoehe,
            l.baujahr,
            l.id_knoten_oben,
            l.id_knoten_unten,
            l.laenge,
            l.twsz,
            l.kanio_id,
            l.kanio_entw,
            l.id_suche
           FROM verundentsorgung.aw_pkt_richtungspfeil p_1,
            verundentsorgung.aw_lin_haltung_v l
          WHERE ((p_1.id_aw_lin_haltung = l.id) AND (p_1.id_st_vw_projekt = l.id_st_vw_projekt) AND (l.medium_kurztext <> 'KR_TEIL'::text))) p;


