            concat(o.name_number, ', ', 'Verbindungen', ', ', vt.kurztext) AS anzeige,
            o.layout,
            (o.id_st_vw_verbindungstyp)::text AS typ
           FROM (verundentsorgung.aw_pkt_verbindungen o
             LEFT JOIN verundentsorgung.st_vw_verbindungstyp vt ON ((o.id_st_vw_verbindungstyp = vt.id)))) a;


