     LEFT JOIN verundentsorgung.aw_pkt_einleitungsstellen_v dio ON ((h.knoten_oben = dio.name_number)))
     LEFT JOIN verundentsorgung.aw_pkt_einleitungsstellen_v diu ON ((h.knoten_unten = diu.name_number)))
  WHERE (h.betriebsstatus_langtext = 'inbetrieb'::text);


