CREATE VIEW verundentsorgung.ka_pkt_kabelnetzknoten_v_label AS
 SELECT t.id,
    t.label_def_id,
    t.fid_parent,
    t.label_text,
    t.horizontal_alignment,
    t.vertical_alignment,
    t.orientation,
    t.winkel,
    t.geometry,
    s.name_number,
    s.projekt_kurztext,
    s.betriebsstatus_kurztext,
    s.eigentuemer_kurztext,
    s.betreiber_kurztext,
    s.material_kurztext,
    s.medium_kurztext,
    s.lagestatus_kurztext,
    s.verwendung_kurztext,
    s.bauteil_kurztext,
    t.table_name,
    s.layout
   FROM verundentsorgung.ka_pkt_label_alt t,
    verundentsorgung.ka_pkt_kabelnetzknoten_v s
  WHERE (t.fid_parent = (s.id)::text);


