--
-- TOC entry 21145 (class 1259 OID 46619299)
-- Name: st_vw_topologie_v; Type: VIEW; Schema: verundentsorgung; Owner: -
--

CREATE VIEW verundentsorgung.st_vw_topologie_v AS
 SELECT b.id,
    b.ident_hist,
    b.kurztext,
    b.langtext,
    concat(b.kurztext, ' (', b.langtext, ')') AS anzeige,
    b.bemerkung,
    b.sortierreihenfolge,
    b.gueltig_von,
    b.gueltig_bis,
    b.angelegt_am,
    b.angelegt_von,
    b.geaendert_am,
    b.geaendert_von,
    b.id_st_vw_projekt
   FROM verundentsorgung.st_vw_topologie b
  WHERE (now() < b.gueltig_bis)
  ORDER BY b.langtext;


