--
-- TOC entry 21948 (class 1259 OID 56780179)
-- Name: ta_pkt_label_v; Type: VIEW; Schema: verundentsorgung; Owner: -
--

CREATE VIEW verundentsorgung.ta_pkt_label_v AS
 SELECT l.id,
    l.drehwinkel,
    l.gueltig_von,
    l.gueltig_bis,
    l.angelegt_am,
    l.angelegt_von,
    l.geaendert_am,
    l.geaendert_von,
    l.bemerkung,
    l.id_st_vw_objektbezeichnung,
    l.ident_hist,
    l.ident_object_hist,
    l.titel,
    l.kommentar,
    l.labeltext,
    l.id_st_vw_labeltyp,
    l.id_st_vw_projekt,
    l.id_st_vw_label_definition,
    l.id_objekt,
    ob.table_schema,
    ob.table_name,
    p.kurztext AS projekt_kurztext,
    p.langtext AS projekt_langtext,
    lt.kurztext AS labeltyp_kurztext,
    lt.langtext AS labeltyp_langtext,
    ld.kurztext AS label_definition_kurztext,
    ld.langtext AS label_definition_langtext,
    l.geometry,
    l.layout,
    concat((l.id)::text, ' ', ob.table_name, ' ', 'TA-Label') AS id_suche
   FROM verundentsorgung.ta_pkt_label l,
    verundentsorgung.st_vw_projekt p,
    verundentsorgung.st_vw_labeltyp lt,
    verundentsorgung.st_vw_label_definition ld,
    verundentsorgung.st_vw_objektbezeichnung ob
  WHERE ((l.id_st_vw_projekt = p.id) AND (lt.id_st_vw_projekt = p.id) AND (ld.id_st_vw_projekt = p.id) AND (ob.id_st_vw_projekt = p.id) AND (l.id_st_vw_labeltyp = lt.id) AND (l.id_st_vw_label_definition = ld.id) AND (l.id_st_vw_objektbezeichnung = ob.id) AND (p.gueltig_bis > now()) AND (l.gueltig_bis > now()) AND (lt.gueltig_bis > now()) AND (ld.gueltig_bis > now()) AND (ob.gueltig_bis > now()));


--
-- TOC entry 112814 (class 0 OID 0)
-- Dependencies: 21948
-- Name: VIEW ta_pkt_label_v; Type: COMMENT; Schema: verundentsorgung; Owner: -
--

COMMENT ON VIEW verundentsorgung.ta_pkt_label_v IS 'techn. Anlagen Pkt Label (VIEW)';


--
-- TOC entry 21944 (class 1259 OID 56548295)
-- Name: ta_pkt_schutzrohr_v; Type: VIEW; Schema: verundentsorgung; Owner: -
--

CREATE VIEW verundentsorgung.ta_pkt_schutzrohr_v AS
 SELECT b.id,
    b.fid_hist,
    b.name_number,
    "left"((b.gueltig_von)::text, 16) AS gueltig_von,
    "left"((b.gueltig_bis)::text, 16) AS gueltig_bis,
    "left"((b.angelegt_am)::text, 10) AS angelegt_am,
    b.angelegt_von,
    "left"((b.geaendert_am)::text, 10) AS geaendert_am,
    b.geaendert_von,
    b.leistungsobjekt,
    b.bemerkung,
    b.id_st_strasse,
    b.hausnummer,
    b.hausnummerzusatz,
    b.lagezusatz,
    b.herkunftsplan,
    b.id_st_vw_projekt,
    b.id_st_vw_betriebsstatus,
    b.id_st_vw_eigentuemer,
    b.id_st_vw_betreiber,
    b.id_st_vw_material,
    b.id_st_vw_medium,
    b.id_st_vw_lagestatus,
    b.geometry,
    s.amt,
    s.gemeinde,
    s.ort,
    s.strasse,
    p.kurztext AS projekt_kurztext,
    p.langtext AS projekt_langtext,
    bs.kurztext AS betriebsstatus_kurztext,
    bs.langtext AS betriebsstatus_langtext,
    eig.kurztext AS eigentuemer_kurztext,
    eig.langtext AS eigentuemer_langtext,
    betr.kurztext AS betreiber_kurztext,
    betr.langtext AS betreiber_langtext,
    mat.kurztext AS material_kurztext,
    mat.langtext AS material_langtext,
    med.kurztext AS medium_kurztext,
    med.langtext AS medium_langtext,
    ls.kurztext AS lagestatus_kurztext,
    ls.langtext AS lagestatus_langtext,
    (b.baujahr)::text AS baujahr,
    b.layout,
    concat(b.name_number, ' ', 'TA-Schutzrohr') AS id_suche,
    b.orientation,
    vw.kurztext AS verwendung_kurztext,
    vw.langtext AS verwendung_langtext
   FROM (((((((((verundentsorgung.ta_pkt_schutzrohr b
     LEFT JOIN verundentsorgung.strassenschluessel_v s ON ((b.id_st_strasse = s.id)))
     LEFT JOIN verundentsorgung.st_vw_projekt p ON ((b.id_st_vw_projekt = p.id)))
     LEFT JOIN verundentsorgung.st_vw_betriebsstatus bs ON ((b.id_st_vw_betriebsstatus = bs.id)))
     LEFT JOIN verundentsorgung.st_vw_eigentuemer eig ON ((b.id_st_vw_eigentuemer = eig.id)))
     LEFT JOIN verundentsorgung.st_vw_betreiber betr ON ((b.id_st_vw_betreiber = betr.id)))
     LEFT JOIN verundentsorgung.st_vw_material mat ON ((b.id_st_vw_material = mat.id)))
     LEFT JOIN verundentsorgung.st_vw_medium med ON ((b.id_st_vw_medium = med.id)))
     LEFT JOIN verundentsorgung.st_vw_lagestatus ls ON ((b.id_st_vw_lagestatus = ls.id)))
     LEFT JOIN verundentsorgung.st_vw_verwendung vw ON ((b.id_st_vw_verwendung = vw.id)))
  WHERE (b.gueltig_bis > now());


