--
-- TOC entry 21161 (class 1259 OID 46620134)
-- Name: wa_lin_topologie_v; Type: VIEW; Schema: verundentsorgung; Owner: -
--

CREATE VIEW verundentsorgung.wa_lin_topologie_v AS
 SELECT o.id,
    o.fid_hist,
    o.name_number,
    o.gueltig_von,
    o.gueltig_bis,
    o.angelegt_am,
    o.angelegt_von,
    o.geaendert_am,
    o.geaendert_von,
    o.leistungsobjekt,
    o.bemerkung,
    o.id_st_strasse,
    o.hausnummer,
    o.hausnummerzusatz,
    o.lagezusatz,
    o.herkunftsplan,
    o.id_st_vw_projekt,
    o.id_st_vw_betriebsstatus,
    o.id_st_vw_eigentuemer,
    o.id_st_vw_betreiber,
    o.id_st_vw_material,
    o.id_st_vw_medium,
    o.id_st_vw_lagestatus,
    o.geometry,
    o.id_knoten_oben,
    o.id_knoten_unten,
    o.baujahr,
    o.migrationsdatum,
    NULL::text AS nennweite,
    o.aussendurchmesser,
    NULL::text AS sohle_einlaufschacht,
    NULL::text AS fallhoehe_einlaufschacht,
    NULL::text AS einlaufnummer,
    NULL::text AS ablaufhoehe,
    NULL::text AS auslaufnummer,
    NULL::text AS einlaufhoehe,
    NULL::text AS sohle_ablaufschacht,
    NULL::text AS haltungsgefaelle,
    o.wandstaerke,
    NULL::text AS plannummer,
    NULL::text AS knoten_oben,
    NULL::text AS knoten_unten,
    o.laenge,
    o.id_st_vw_verlegetyp,
    NULL::text AS id_st_vw_einlaufnummer,
    NULL::text AS farbwert,
    'wa_lin_wasserleitung'::text AS table_name,
    o.layout,
    concat(o.name_number, ' ', 'WA-LIN-Topologie') AS id_suche
   FROM verundentsorgung.wa_lin_wasserleitung o;


