--
-- TOC entry 23245 (class 1259 OID 63542783)
-- Name: wa_pkt_hydrant_messwerte; Type: TABLE; Schema: verundentsorgung; Owner: -
--

CREATE TABLE verundentsorgung.wa_pkt_hydrant_messwerte (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    id_wa_pkt_hydrant uuid DEFAULT '00000000-0000-0000-0000-000000000000'::uuid NOT NULL,
    fid_hist text DEFAULT 'unbekannt'::text NOT NULL,
    name_number text DEFAULT 'unbekannt'::text NOT NULL,
    gueltig_von timestamp with time zone DEFAULT now() NOT NULL,
    gueltig_bis timestamp with time zone DEFAULT '2100-01-01 00:00:00+01'::timestamp with time zone NOT NULL,
    angelegt_am timestamp with time zone DEFAULT now() NOT NULL,
    angelegt_von text DEFAULT 'unbekannt'::text NOT NULL,
    geaendert_am timestamp with time zone DEFAULT now() NOT NULL,
    geaendert_von text DEFAULT 'unbekannt'::text NOT NULL,
    leistungsobjekt text,
    bemerkung text,
    id_st_strasse uuid DEFAULT '00000000-0000-0000-0000-000000000000'::uuid NOT NULL,
    hausnummer text,
    hausnummerzusatz text,
    lagezusatz text,
    id_st_vw_projekt uuid DEFAULT '00000000-0000-0000-0000-000000000000'::uuid NOT NULL,
    id_st_vw_betriebsstatus uuid DEFAULT '00000000-0000-0000-0000-000000000000'::uuid NOT NULL,
    id_st_vw_eigentuemer uuid DEFAULT '00000000-0000-0000-0000-000000000000'::uuid NOT NULL,
    id_st_vw_betreiber uuid DEFAULT '00000000-0000-0000-0000-000000000000'::uuid NOT NULL,
    id_st_vw_material uuid DEFAULT '00000000-0000-0000-0000-000000000000'::uuid NOT NULL,
    id_st_vw_medium uuid DEFAULT '00000000-0000-0000-0000-000000000000'::uuid NOT NULL,
    id_st_vw_lagestatus uuid DEFAULT '00000000-0000-0000-0000-000000000000'::uuid NOT NULL,
    id_st_vw_model_design uuid DEFAULT '00000000-0000-0000-0000-000000000000'::uuid NOT NULL,
    id_st_vw_nennweite_hydrant uuid DEFAULT '00000000-0000-0000-0000-000000000000'::uuid NOT NULL,
    id_st_vw_nennweite_dn_tw_leitung uuid DEFAULT '00000000-0000-0000-0000-000000000000'::uuid NOT NULL,
    id_st_vw_hydranttyp uuid DEFAULT '00000000-0000-0000-0000-000000000000'::uuid NOT NULL,
    id_st_vw_hersteller uuid DEFAULT '00000000-0000-0000-0000-000000000000'::uuid NOT NULL,
    ext_mess_zeile character varying,
    ext_mess_datum character varying,
    ext_mess_durchfluss character varying,
    ext_mess_erfassungruhedruck character varying,
    ext_hyd_oberflaeche character varying,
    ext_hyd_vertragsart character varying,
    ext_hyd_vorschieber character varying,
    ext_hyd_betriebshydrant character varying,
    migrationsdatum timestamp with time zone DEFAULT now() NOT NULL,
    orientation numeric(10,2),
    geometry public.geometry(Point,25833) NOT NULL,
    layout jsonb
);


--
-- TOC entry 23247 (class 1259 OID 63542950)
-- Name: wa_pkt_hydrant_messwerte_puffer_v; Type: VIEW; Schema: verundentsorgung; Owner: -
--

CREATE VIEW verundentsorgung.wa_pkt_hydrant_messwerte_puffer_v AS
 SELECT b.id,
    b.fid_hist,
    b.name_number,
    "left"((b.gueltig_von)::text, 16) AS gueltig_von,
    "left"((b.gueltig_bis)::text, 16) AS gueltig_bis,
    "left"((b.angelegt_am)::text, 10) AS angelegt_am,
    b.angelegt_von,
    "left"((b.geaendert_am)::text, 10) AS geaendert_am,
    b.geaendert_von,
    b.leistungsobjekt,
    b.bemerkung,
    b.id_st_strasse,
    b.hausnummer,
    b.hausnummerzusatz,
    b.lagezusatz,
    b.id_st_vw_projekt,
    b.id_st_vw_betriebsstatus,
    b.id_st_vw_eigentuemer,
    b.id_st_vw_betreiber,
    b.id_st_vw_material,
    b.id_st_vw_medium,
    b.id_st_vw_lagestatus,
    public.st_buffer(b.geometry, (150)::double precision) AS geometry,
    s.amt,
    s.gemeinde,
    s.ort,
    s.strasse,
    p.kurztext AS projekt_kurztext,
    p.langtext AS projekt_langtext,
    bs.kurztext AS betriebsstatus_kurztext,
    bs.langtext AS betriebsstatus_langtext,
    eig.kurztext AS eigentuemer_kurztext,
    eig.langtext AS eigentuemer_langtext,
    betr.kurztext AS betreiber_kurztext,
    betr.langtext AS betreiber_langtext,
    mat.kurztext AS material_kurztext,
    mat.langtext AS material_langtext,
    med.kurztext AS medium_kurztext,
    med.langtext AS medium_langtext,
    ls.kurztext AS lagestatus_kurztext,
    ls.langtext AS lagestatus_langtext,
    md.kurztext AS modell_design_kurztext,
    md.langtext AS modell_design_langtext,
    nh.kurztext AS nennweite_hydrant_kurztext,
    nh.langtext AS nennweite_hydrant_langtext,
    dt.kurztext AS nennweite_dn_tw_leitung_kurztext,
    dt.langtext AS nennweite_dn_tw_leitung_langtext,
    ht.kurztext AS hydranttyp_kurztext,
    ht.langtext AS hydranttyp_langtext,
    b.ext_mess_zeile,
    b.ext_mess_datum,
    b.ext_mess_durchfluss,
    b.ext_mess_erfassungruhedruck,
    b.ext_hyd_oberflaeche,
    b.ext_hyd_vertragsart,
    b.ext_hyd_vorschieber,
    b.ext_hyd_betriebshydrant,
    b.orientation,
    h.kurztext AS hersteller_kurztext,
    h.langtext AS hersteller_langtext,
    b.layout,
    concat(b.name_number, ' ', 'WA-Hydrant') AS id_suche,
    concat('WA_HYDRANT_', b.name_number) AS kanio_id,
